-- Sources: Esmaül Hüsna, Diyanet Quran translation, Sahih Bukhari/Muslim

truncate table public.content_items restart identity cascade;

insert into public.content_items (type, category, recommended_time, translations, is_active) values

-- ============================================================
-- 99 ESMAÜL HÜSNA
-- ============================================================

('esma','dhikr','any','{"tr":{"content":"Allah, tüm varlıkların yaratıcısı ve sahibi olan yüce isimdir. Bütün güzel isimler ve yüce sıfatlar O''na aittir.","arabicText":"اللَّهُ","transliteration":"Allâh","source":"Esma-ül Hüsna"},"en":{"content":"Allah is the greatest and most comprehensive name of God, encompassing all His attributes. All other beautiful names belong to Him.","arabicText":"اللَّهُ","transliteration":"Allâh","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"Er-Rahmân, dünyada bütün mahlûkata merhamet eden, rahmeti her şeyi kuşatan demektir. Bu isim yalnızca Allah''a mahsustur.","arabicText":"الرَّحْمَٰنُ","transliteration":"er-Rahmân","source":"Esma-ül Hüsna"},"en":{"content":"Ar-Rahman means the Most Gracious, whose mercy encompasses all of creation in this world. This name belongs exclusively to Allah.","arabicText":"الرَّحْمَٰنُ","transliteration":"er-Rahmân","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"Er-Rahîm, ahirette yalnızca müminlere özel rahmet ve merhamet gösteren demektir. O''nun rahmeti sonsuz ve tükenmezdir.","arabicText":"الرَّحِيمُ","transliteration":"er-Rahîm","source":"Esma-ül Hüsna"},"en":{"content":"Ar-Rahim means the Most Merciful, whose special mercy in the hereafter is reserved for the believers. His mercy is boundless and inexhaustible.","arabicText":"الرَّحِيمُ","transliteration":"er-Rahîm","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Melik, mülkün ve kâinatın gerçek sahibi ve hükümdarı demektir. Her şey O''nun hükmü altındadır.","arabicText":"الْمَلِكُ","transliteration":"el-Melik","source":"Esma-ül Hüsna"},"en":{"content":"Al-Malik means the King and Sovereign, the true owner and ruler of all existence. Everything is under His dominion.","arabicText":"الْمَلِكُ","transliteration":"el-Melik","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Kuddûs, her türlü eksiklik ve noksanlıktan münezzeh, son derece temiz ve mukaddes olan demektir. O''nun zatı her kusurdan uzaktır.","arabicText":"الْقُدُّوسُ","transliteration":"el-Kuddûs","source":"Esma-ül Hüsna"},"en":{"content":"Al-Quddus means the Most Pure and Holy, free from any deficiency or imperfection. His essence is exalted above all flaws.","arabicText":"الْقُدُّوسُ","transliteration":"el-Kuddûs","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"Es-Selâm, kullarına esenlik ve güvenlik veren, cennetin adı da olan yüce isimdir. Her türlü bela ve afetten selamet verir.","arabicText":"السَّلَامُ","transliteration":"es-Selâm","source":"Esma-ül Hüsna"},"en":{"content":"As-Salam means the Source of Peace, who grants safety and well-being to His servants. He is free from all imperfection and is the name of Paradise.","arabicText":"السَّلَامُ","transliteration":"es-Selâm","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Mü''min, kullarına güven veren, onları her türlü korkudan emin kılan demektir. Peygamberleri doğrulayan ve inancı kalplere yerleştiren O''dur.","arabicText":"الْمُؤْمِنُ","transliteration":"el-Mü''min","source":"Esma-ül Hüsna"},"en":{"content":"Al-Mu''min means the Granter of Security, who gives faith and safety to His servants. He confirms the truthfulness of His prophets and instills belief in hearts.","arabicText":"الْمُؤْمِنُ","transliteration":"el-Mü''min","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Müheymin, gözetip koruyan, her şeyi denetim altında tutan ve hâkim olan demektir. Her varlığın işini kontrol eder ve yönetir.","arabicText":"الْمُهَيْمِنُ","transliteration":"el-Müheymin","source":"Esma-ül Hüsna"},"en":{"content":"Al-Muhaymin means the Guardian and Overseer, who watches over and protects all things. He controls and manages the affairs of every being.","arabicText":"الْمُهَيْمِنُ","transliteration":"el-Müheymin","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Azîz, her şeye galip gelen, güçlü ve yenilmez olan demektir. İzzet ve şeref yalnızca O''na aittir.","arabicText":"الْعَزِيزُ","transliteration":"el-Azîz","source":"Esma-ül Hüsna"},"en":{"content":"Al-Aziz means the Almighty and All-Powerful, the Invincible One who prevails over all things. All might and honor belong exclusively to Him.","arabicText":"الْعَزِيزُ","transliteration":"el-Azîz","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Cebbâr, dilediğini zorla yaptırabilen, kırıkları onaran ve eksikleri tamamlayan demektir. Büyüklük ve kudret yalnızca O''na mahsustur.","arabicText":"الْجَبَّارُ","transliteration":"el-Cebbâr","source":"Esma-ül Hüsna"},"en":{"content":"Al-Jabbar means the Compeller who enforces His will, mends the broken and completes the deficient. Greatness and overwhelming power belong only to Him.","arabicText":"الْجَبَّارُ","transliteration":"el-Cebbâr","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Mütekebbir, büyüklük ve ululuk yalnızca kendisine ait olan, her şeyin üstünde yüce olan demektir. Kibriya O''nun şânıdır.","arabicText":"الْمُتَكَبِّرُ","transliteration":"el-Mütekebbir","source":"Esma-ül Hüsna"},"en":{"content":"Al-Mutakabbir means the Supremely Great, whose greatness and majesty belong to Him alone. He is exalted above all things and grandeur is His attribute.","arabicText":"الْمُتَكَبِّرُ","transliteration":"el-Mütekebbir","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Hâlık, her şeyi yoktan var eden, yaratan demektir. O''nun yaratması hiçbir örneğe ve malzemeye ihtiyaç duymaz.","arabicText":"الْخَالِقُ","transliteration":"el-Hâlık","source":"Esma-ül Hüsna"},"en":{"content":"Al-Khaliq means the Creator who brings everything into existence from nothing. His creation requires no model or material to work from.","arabicText":"الْخَالِقُ","transliteration":"el-Hâlık","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Bâri'', yarattıklarını birbirinden ayırt edecek şekilde düzgün ve uyumlu biçimde var eden demektir. Her varlığı kusursuz bir denge ile ortaya çıkarır.","arabicText":"الْبَارِئُ","transliteration":"el-Bâri''","source":"Esma-ül Hüsna"},"en":{"content":"Al-Bari'' means the Originator who creates all beings in perfect order and harmony, distinguishing each from the other. He brings forth every creature with flawless balance.","arabicText":"الْبَارِئُ","transliteration":"el-Bâri''","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Musavvir, yarattıklarına dilediği şekli ve sureti veren demektir. Her varlığın biçimini en güzel ve en uygun hâlde tasarlayan O''dur.","arabicText":"الْمُصَوِّرُ","transliteration":"el-Musavvir","source":"Esma-ül Hüsna"},"en":{"content":"Al-Musawwir means the Fashioner who gives every created being its unique form and image. He designs the shape of every creature in the most beautiful and fitting way.","arabicText":"الْمُصَوِّرُ","transliteration":"el-Musavvir","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Ğaffâr, kullarının günahlarını defalarca bağışlayan, tevbeye karşılık veren demektir. O''nun mağfireti geniş ve tükenmezdir.","arabicText":"الْغَفَّارُ","transliteration":"el-Ğaffâr","source":"Esma-ül Hüsna"},"en":{"content":"Al-Ghaffar means the Repeatedly Forgiving, who pardons the sins of His servants again and again in response to repentance. His forgiveness is vast and inexhaustible.","arabicText":"الْغَفَّارُ","transliteration":"el-Ğaffâr","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Kahhâr, her şeye hükmeden, her şeyi iradesine boyun eğdiren demektir. Hiçbir güç O''nun önünde duramaz.","arabicText":"الْقَهَّارُ","transliteration":"el-Kahhâr","source":"Esma-ül Hüsna"},"en":{"content":"Al-Qahhar means the All-Subduer who overpowers and subjugates everything to His will. No power can stand before Him.","arabicText":"الْقَهَّارُ","transliteration":"el-Kahhâr","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Vehhâb, karşılıksız ve sürekli olarak bağışlayan, lütuf ve ihsanını esirgemeyen demektir. Her hayrın ve nimetin kaynağı O''dur.","arabicText":"الْوَهَّابُ","transliteration":"el-Vehhâb","source":"Esma-ül Hüsna"},"en":{"content":"Al-Wahhab means the Bestower who gives freely and continuously without expecting anything in return. He is the source of every good and every blessing.","arabicText":"الْوَهَّابُ","transliteration":"el-Vehhâb","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"Er-Razzâk, tüm mahlûkata rızkını veren, geçimlerini sağlayan demektir. O''nun hazinesi hiç tükenmez ve her canlının rızkını o verir.","arabicText":"الرَّزَّاقُ","transliteration":"er-Razzâk","source":"Esma-ül Hüsna"},"en":{"content":"Ar-Razzaq means the Provider who sustains all creatures and grants them their provisions. His treasures never diminish and He provides for every living being.","arabicText":"الرَّزَّاقُ","transliteration":"er-Razzâk","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Fettâh, kullar için hayır kapılarını açan, çözümsüz görünen sorunlara çözüm bulan demektir. Hükmü ve hakikati en iyi bilen O''dur.","arabicText":"الْفَتَّاحُ","transliteration":"el-Fettâh","source":"Esma-ül Hüsna"},"en":{"content":"Al-Fattah means the Opener who opens the gates of good for His servants and resolves seemingly impossible difficulties. He is the best judge and the knower of truth.","arabicText":"الْفَتَّاحُ","transliteration":"el-Fettâh","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Alîm, her şeyi en ince ayrıntısına kadar bilen, geçmişi geleceği ve sırları eksiksiz kavrayan demektir. O''nun ilmi sonsuz ve kuşatıcıdır.","arabicText":"الْعَلِيمُ","transliteration":"el-Alîm","source":"Esma-ül Hüsna"},"en":{"content":"Al-Alim means the All-Knowing who knows everything down to the finest detail, comprehending past, future and all secrets perfectly. His knowledge is infinite and all-encompassing.","arabicText":"الْعَلِيمُ","transliteration":"el-Alîm","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Kâbid, rızıkları daraltan ve ruhları kabzeden demektir. Hikmetiyle dilediğine darlık verir, bu da bir sınavın parçasıdır.","arabicText":"الْقَابِضُ","transliteration":"el-Kâbid","source":"Esma-ül Hüsna"},"en":{"content":"Al-Qabid means the Withholder who constricts provisions and takes souls. In His wisdom He grants constriction to whom He wills, and this too is part of the divine test.","arabicText":"الْقَابِضُ","transliteration":"el-Kâbid","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Bâsıt, rızıkları genişleten ve rahmetini yayan demektir. Hikmetiyle dilediğine bolluk ve ferahlık verir.","arabicText":"الْبَاسِطُ","transliteration":"el-Bâsıt","source":"Esma-ül Hüsna"},"en":{"content":"Al-Basit means the Expander who widens provisions and spreads His mercy. In His wisdom He grants abundance and ease to whom He wills.","arabicText":"الْبَاسِطُ","transliteration":"el-Bâsıt","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Hâfıd, dilediğini alçaltan, kibirlenenleri zelil kılan demektir. Ululuk ve büyüklük yalnızca O''na aittir, kimse O''na ortak olamaz.","arabicText":"الْخَافِضُ","transliteration":"el-Hâfıd","source":"Esma-ül Hüsna"},"en":{"content":"Al-Khafid means the Abaser who humbles whomever He wills. Greatness belongs only to Him and no one can be His partner in majesty.","arabicText":"الْخَافِضُ","transliteration":"el-Hâfıd","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"Er-Râfi'', dilediğini yücelten, mertebesini artıran demektir. Gerçek yücelme ve şeref O''nun ihsanı ile olur.","arabicText":"الرَّافِعُ","transliteration":"er-Râfi''","source":"Esma-ül Hüsna"},"en":{"content":"Ar-Rafi'' means the Exalter who raises and elevates whomever He wills. True elevation and honor come only through His bestowal.","arabicText":"الرَّافِعُ","transliteration":"er-Râfi''","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Mu''izz, dilediğini güçlü ve şerefli kılan demektir. İzzet ve onur yalnızca O''nun elindedir ve O dilediğine verir.","arabicText":"الْمُعِزُّ","transliteration":"el-Mu''izz","source":"Esma-ül Hüsna"},"en":{"content":"Al-Mu''izz means the Bestower of Honor who grants strength and dignity to whomever He wills. All honor and esteem are in His hand and He gives to whom He pleases.","arabicText":"الْمُعِزُّ","transliteration":"el-Mu''izz","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Müzill, dilediğini zelil ve perişan kılan demektir. Zilletin de izzetin de sahibi yalnızca O''dur; hükmüne kimse itiraz edemez.","arabicText":"الْمُذِلُّ","transliteration":"el-Müzill","source":"Esma-ül Hüsna"},"en":{"content":"Al-Mudhill means the Humiliator who disgraces and debases whomever He wills. He alone is the owner of both humiliation and honor; none can contest His decree.","arabicText":"الْمُذِلُّ","transliteration":"el-Müzill","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"Es-Semî'', her sesi ve her sözü duyan, gizli açık tüm sesleri işiten demektir. Hiçbir dua ve yakarış O''ndan gizli kalmaz.","arabicText":"السَّمِيعُ","transliteration":"es-Semî''","source":"Esma-ül Hüsna"},"en":{"content":"As-Sami'' means the All-Hearing who hears every sound and every word, whether hidden or open. No prayer or supplication is concealed from Him.","arabicText":"السَّمِيعُ","transliteration":"es-Semî''","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Basîr, her şeyi gören, en küçük ayrıntıyı bile fark eden demektir. Karanlıkta hareket eden bir karıncanın adımını bile görür.","arabicText":"الْبَصِيرُ","transliteration":"el-Basîr","source":"Esma-ül Hüsna"},"en":{"content":"Al-Basir means the All-Seeing who perceives every thing, even the smallest detail. He sees even the steps of an ant moving in the darkness.","arabicText":"الْبَصِيرُ","transliteration":"el-Basîr","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Hakem, her şey hakkında hüküm veren, kullar arasında adaletle hükmeden demektir. Hükmü en doğru ve en hakkaniyetlidir.","arabicText":"الْحَكَمُ","transliteration":"el-Hakem","source":"Esma-ül Hüsna"},"en":{"content":"Al-Hakam means the Judge who passes judgment on all things and rules between His servants with justice. His judgment is the most correct and the most equitable.","arabicText":"الْحَكَمُ","transliteration":"el-Hakem","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Adl, son derece adil ve hakkaniyetli olan demektir. Zerre kadar zulüm etmez; her hakkı sahibine tastamam verir.","arabicText":"الْعَدْلُ","transliteration":"el-Adl","source":"Esma-ül Hüsna"},"en":{"content":"Al-Adl means the Utterly Just, who is perfectly equitable and fair. He does not wrong anyone even by an atom''s weight; He gives every right to its owner in full.","arabicText":"الْعَدْلُ","transliteration":"el-Adl","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Latîf, en ince sırları bilen ve kullarına en lütufkâr biçimde yaklaşan demektir. İlmi her zerreye ulaşır ve lütfu her yerde kendini gösterir.","arabicText":"اللَّطِيفُ","transliteration":"el-Latîf","source":"Esma-ül Hüsna"},"en":{"content":"Al-Latif means the Subtly Kind, who knows the finest secrets and approaches His servants with the utmost gentleness. His knowledge reaches every atom and His grace manifests everywhere.","arabicText":"اللَّطِيفُ","transliteration":"el-Latîf","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Habîr, her şeyden haberdar olan, tüm varlıkların iç yüzünü bilen demektir. Hiçbir şey O''nun bilgisinden kaçamaz.","arabicText":"الْخَبِيرُ","transliteration":"el-Habîr","source":"Esma-ül Hüsna"},"en":{"content":"Al-Khabir means the All-Aware, who is fully informed of all things and knows the inner reality of every being. Nothing can escape His knowledge.","arabicText":"الْخَبِيرُ","transliteration":"el-Habîr","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Halîm, hemen ceza vermeyip yumuşak davranan, günahkârlara süre tanıyan demektir. Öfkelenmez, acele etmez; sabrı ve hilmi sonsuzdur.","arabicText":"الْحَلِيمُ","transliteration":"el-Halîm","source":"Esma-ül Hüsna"},"en":{"content":"Al-Halim means the Forbearing, who acts with clemency and does not rush to punish, granting respite to sinners. He does not get angry hastily; His patience and forbearance are infinite.","arabicText":"الْحَلِيمُ","transliteration":"el-Halîm","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Azîm, sonsuz büyüklük ve ululuk sahibi olan demektir. Akılların O''nun azametini kavraması mümkün değildir.","arabicText":"الْعَظِيمُ","transliteration":"el-Azîm","source":"Esma-ül Hüsna"},"en":{"content":"Al-Azim means the Supremely Great, who possesses infinite majesty and grandeur. It is impossible for minds to fully comprehend His magnificence.","arabicText":"الْعَظِيمُ","transliteration":"el-Azîm","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Ğafûr, çok bağışlayan, günahları örten ve affeden demektir. Tevbe eden kulunu hemen bağışlar ve günah izlerini siler.","arabicText":"الْغَفُورُ","transliteration":"el-Ğafûr","source":"Esma-ül Hüsna"},"en":{"content":"Al-Ghafur means the Most Forgiving, who pardons abundantly and conceals sins. He immediately forgives the servant who repents and erases all traces of the sin.","arabicText":"الْغَفُورُ","transliteration":"el-Ğafûr","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"Eş-Şekûr, az ameli çok mükâfatla karşılayan, şükredenlere nimetini artıran demektir. O''nun verdiği ödül sınır tanımaz.","arabicText":"الشَّكُورُ","transliteration":"eş-Şekûr","source":"Esma-ül Hüsna"},"en":{"content":"Ash-Shakur means the Most Appreciative, who rewards small deeds with great recompense and increases blessings for those who are grateful. The reward He gives knows no limit.","arabicText":"الشَّكُورُ","transliteration":"eş-Şekûr","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Aliyy, yüce ve yüksek olan, her şeyin üstünde olan demektir. Hiçbir şey O''na denk veya ortak olamaz; O her şeyin üzerindedir.","arabicText":"الْعَلِيُّ","transliteration":"el-Aliyy","source":"Esma-ül Hüsna"},"en":{"content":"Al-Ali means the Most High, exalted and elevated above all things. Nothing can be His equal or partner; He is above everything.","arabicText":"الْعَلِيُّ","transliteration":"el-Aliyy","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Kebîr, sonsuz büyüklük sahibi olan demektir. Büyüklükte O''nun eşi ve benzeri yoktur; her şeyden üstün ve her şeyin üzerindedir.","arabicText":"الْكَبِيرُ","transliteration":"el-Kebîr","source":"Esma-ül Hüsna"},"en":{"content":"Al-Kabir means the Most Great, who possesses boundless greatness. Nothing equals or resembles Him in greatness; He is above and superior to all things.","arabicText":"الْكَبِيرُ","transliteration":"el-Kebîr","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Hafîz, tüm varlıkları koruyan ve muhafaza eden demektir. Evrenin düzenini tutan, kullarını gözetip belalardan saklayan O''dur.","arabicText":"الْحَفِيظُ","transliteration":"el-Hafîz","source":"Esma-ül Hüsna"},"en":{"content":"Al-Hafiz means the All-Preserver who protects and safeguards all beings. He maintains the order of the universe and guards His servants from calamity.","arabicText":"الْحَفِيظُ","transliteration":"el-Hafîz","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Mukît, her canlıya rızık ve kuvvet veren, bedenin ve ruhun gıdasını sağlayan demektir. Her varlığın ihtiyacını karşılamaya muktedirdir.","arabicText":"الْمُقِيتُ","transliteration":"el-Mukît","source":"Esma-ül Hüsna"},"en":{"content":"Al-Muqit means the Sustainer who provides nourishment and strength to every living creature, supplying food for both body and soul. He has power to meet the needs of every being.","arabicText":"الْمُقِيتُ","transliteration":"el-Mukît","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Hasîb, her şeyin hesabını gören, kulların amellerini bilen ve karşılığını veren demektir. Hesabını en dakik ve adil biçimde tutar.","arabicText":"الْحَسِيبُ","transliteration":"el-Hasîb","source":"Esma-ül Hüsna"},"en":{"content":"Al-Hasib means the Reckoner who takes account of all things, knows the deeds of His servants and recompenses them accordingly. He keeps record in the most precise and fair manner.","arabicText":"الْحَسِيبُ","transliteration":"el-Hasîb","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Celîl, azamet ve ululuk sahibi olan, yüce ve heybet uyandıran demektir. Celâl ve heybet O''na mahsus güzelliklerdir.","arabicText":"الْجَلِيلُ","transliteration":"el-Celîl","source":"Esma-ül Hüsna"},"en":{"content":"Al-Jalil means the Majestic, who possesses supreme glory and grandeur. Majesty and awe are attributes that belong to Him alone.","arabicText":"الْجَلِيلُ","transliteration":"el-Celîl","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Kerîm, çok cömert ve ikram sahibi olan demektir. Kimseyi kapısından boş çevirmez; lütuf ve ihsanı boldur.","arabicText":"الْكَرِيمُ","transliteration":"el-Kerîm","source":"Esma-ül Hüsna"},"en":{"content":"Al-Karim means the Most Generous and Noble, who turns no one away empty-handed. His grace and benevolence are abundant.","arabicText":"الْكَرِيمُ","transliteration":"el-Kerîm","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"Er-Rakîb, her şeyi gözetleyen, hiçbir şeyin gözünden kaçmadığı demektir. Her anımızı, her düşüncemizi ve her eylemimizi izler.","arabicText":"الرَّقِيبُ","transliteration":"er-Rakîb","source":"Esma-ül Hüsna"},"en":{"content":"Ar-Raqib means the Ever-Watchful, from whose sight nothing escapes. He observes every moment, every thought and every action of ours.","arabicText":"الرَّقِيبُ","transliteration":"er-Rakîb","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Mücîb, duaları kabul eden ve dileklere icabet eden demektir. Kendisine yalvaran her kulunun sesini duyar ve ona cevap verir.","arabicText":"الْمُجِيبُ","transliteration":"el-Mücîb","source":"Esma-ül Hüsna"},"en":{"content":"Al-Mujib means the Responsive Answerer who accepts prayers and responds to requests. He hears the call of every servant who implores Him and answers them.","arabicText":"الْمُجِيبُ","transliteration":"el-Mücîb","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Vâsi'', rahmeti, ilmi ve kudreti her şeyi kuşatan geniş demektir. Hiçbir şey O''nun ihata ettiği sınırın dışında kalamaz.","arabicText":"الْوَاسِعُ","transliteration":"el-Vâsi''","source":"Esma-ül Hüsna"},"en":{"content":"Al-Wasi'' means the All-Encompassing, whose mercy, knowledge and power embrace all things. Nothing can exist beyond the bounds of His encompassment.","arabicText":"الْوَاسِعُ","transliteration":"el-Vâsi''","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Hakîm, mutlak hikmet sahibi olan, her işi yerli yerinde ve en uygun biçimde yapan demektir. Hükümleri ve takdirleri en mükemmel hikmete dayanır.","arabicText":"الْحَكِيمُ","transliteration":"el-Hakîm","source":"Esma-ül Hüsna"},"en":{"content":"Al-Hakim means the All-Wise who possesses absolute wisdom and does everything in its most proper and fitting manner. His decrees and ordainments rest on the most perfect wisdom.","arabicText":"الْحَكِيمُ","transliteration":"el-Hakîm","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Vedûd, kullarını seven ve sevilmeye layık olan demektir. Müminlerin kalbine birbirlerine karşı sevgi koyan ve onları seven O''dur.","arabicText":"الْوَدُودُ","transliteration":"el-Vedûd","source":"Esma-ül Hüsna"},"en":{"content":"Al-Wadud means the Most Loving who loves His servants and is worthy of being loved. He places love in the hearts of believers for one another and loves them dearly.","arabicText":"الْوَدُودُ","transliteration":"el-Vedûd","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Mecîd, şan ve şeref sahibi, hem azamet hem de kerem sahibi olan demektir. Yüceliği ve cömertliği bir arada taşır.","arabicText":"الْمَجِيدُ","transliteration":"el-Mecîd","source":"Esma-ül Hüsna"},"en":{"content":"Al-Majid means the Most Glorious, who possesses both supreme majesty and boundless generosity. He combines sublimity and munificence in His essence.","arabicText":"الْمَجِيدُ","transliteration":"el-Mecîd","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Bâis, ölüleri dirilten, kıyamet gününde tüm insanları hesap için yeniden var eden demektir. O, her şeyden haberdar olarak onları diriltir.","arabicText":"الْبَاعِثُ","transliteration":"el-Bâis","source":"Esma-ül Hüsna"},"en":{"content":"Al-Ba''ith means the Resurrector who brings the dead back to life and raises all of humanity on the Day of Judgment for reckoning. He resurrects them while being fully aware of everything.","arabicText":"الْبَاعِثُ","transliteration":"el-Bâis","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"Eş-Şehîd, her yerde hazır bulunan ve her şeye tanıklık eden demektir. Hiçbir gizli iş O''ndan uzakta değildir; her şeye bizzat şahittir.","arabicText":"الشَّهِيدُ","transliteration":"eş-Şehîd","source":"Esma-ül Hüsna"},"en":{"content":"Ash-Shahid means the Ever-Present Witness who is present everywhere and bears witness to all things. No hidden matter is distant from Him; He Himself witnesses everything.","arabicText":"الشَّهِيدُ","transliteration":"eş-Şehîd","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Hakk, varlığı zorunlu olan, gerçek ve değişmez olan demektir. Söyledikleri ve vaadleri kesinlikle doğrudur; O''ndan başka gerçek yoktur.","arabicText":"الْحَقُّ","transliteration":"el-Hakk","source":"Esma-ül Hüsna"},"en":{"content":"Al-Haqq means the Absolute Truth, whose existence is necessary and whose reality is immutable. His words and promises are certainly true; there is no reality other than Him.","arabicText":"الْحَقُّ","transliteration":"el-Hakk","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Vekîl, işlerini tevdi edenlerin işlerini en iyi biçimde yürüten, güvenilir vekil demektir. Kendisine tevekkül edene her işinde kâfidir.","arabicText":"الْوَكِيلُ","transliteration":"el-Vekîl","source":"Esma-ül Hüsna"},"en":{"content":"Al-Wakil means the Trustee who manages the affairs of those who entrust their matters to Him in the best possible way. He is sufficient for every matter of the one who relies upon Him.","arabicText":"الْوَكِيلُ","transliteration":"el-Vekîl","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Kaviyy, sonsuz güç ve kuvvet sahibi olan demektir. Hiçbir şey O''nun gücünü kıramaz ve O hiçbir şeyden aciz değildir.","arabicText":"الْقَوِيُّ","transliteration":"el-Kaviyy","source":"Esma-ül Hüsna"},"en":{"content":"Al-Qawiyy means the All-Powerful, who possesses infinite strength and might. Nothing can diminish His power and He is incapable of nothing.","arabicText":"الْقَوِيُّ","transliteration":"el-Kaviyy","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Metîn, son derece sağlam ve sarsılmaz güç sahibi olan demektir. Kudreti hiç azalmaz ve hiçbir şey O''nu yoramaz ya da zayıflatamaz.","arabicText":"الْمَتِينُ","transliteration":"el-Metîn","source":"Esma-ül Hüsna"},"en":{"content":"Al-Matin means the Firm and Steadfast, who possesses absolutely unshakeable power. His might never diminishes and nothing can tire or weaken Him.","arabicText":"الْمَتِينُ","transliteration":"el-Metîn","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Veliyy, müminlerin dostu ve yardımcısı, onları koruyan ve destekleyen demektir. Dostluk ettiği kimseyi asla yalnız bırakmaz.","arabicText":"الْوَلِيُّ","transliteration":"el-Veliyy","source":"Esma-ül Hüsna"},"en":{"content":"Al-Wali means the Protecting Friend and Guardian of the believers, who supports and shields them. He never abandons those with whom He takes friendship.","arabicText":"الْوَلِيُّ","transliteration":"el-Veliyy","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Hamîd, her türlü övgüye ve şükre layık olan demektir. Tüm hamdler ve güzel övgüler yalnızca O''na aittir.","arabicText":"الْحَمِيدُ","transliteration":"el-Hamîd","source":"Esma-ül Hüsna"},"en":{"content":"Al-Hamid means the Most Praiseworthy, who is deserving of all praise and gratitude. All praise and beautiful commendations belong exclusively to Him.","arabicText":"الْحَمِيدُ","transliteration":"el-Hamîd","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Muhsî, her şeyi sayan ve kaydeden, zerreden arşa her şeyden eksiksiz haberdar olan demektir. Sonsuz ilmiyle tüm varlıkları ihsâ eder.","arabicText":"الْمُحْصِي","transliteration":"el-Muhsî","source":"Esma-ül Hüsna"},"en":{"content":"Al-Muhsi means the All-Enumerating, who counts and records everything, being perfectly informed of everything from an atom to the Throne. He enumerates all beings with His infinite knowledge.","arabicText":"الْمُحْصِي","transliteration":"el-Muhsî","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Mübdi'', her şeyi ilk kez yoktan var eden demektir. Bir örnek veya model olmaksızın yaratmaya başlayan yalnızca O''dur.","arabicText":"الْمُبْدِئُ","transliteration":"el-Mübdi''","source":"Esma-ül Hüsna"},"en":{"content":"Al-Mubdi'' means the Originator who brings everything into being for the first time out of nothing. He alone is the one who begins creation without any prior model or example.","arabicText":"الْمُبْدِئُ","transliteration":"el-Mübdi''","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Muîd, yaratılanları yok ettikten sonra yeniden dirilten demektir. Kıyamet gününde her şeyi ilk yarattığı gibi kolaylıkla yeniden var eder.","arabicText":"الْمُعِيدُ","transliteration":"el-Muîd","source":"Esma-ül Hüsna"},"en":{"content":"Al-Mu''id means the Restorer who brings back into existence what has been destroyed. On the Day of Resurrection He recreates everything with the same ease as He first created it.","arabicText":"الْمُعِيدُ","transliteration":"el-Muîd","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Muhyî, hayat veren, ölüleri dirilten ve canlılara can bahşeden demektir. Tüm hayatın kaynağı ve sahibi O''dur.","arabicText":"الْمُحْيِي","transliteration":"el-Muhyî","source":"Esma-ül Hüsna"},"en":{"content":"Al-Muhyi means the Giver of Life who bestows life, revives the dead and grants vitality to all living things. He is the source and owner of all life.","arabicText":"الْمُحْيِي","transliteration":"el-Muhyî","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Mümît, ölümü yaratan ve dilediği varlığın canını alan demektir. Hayat gibi ölüm de tamamen O''nun elindedir ve yalnızca O''nun izniyle olur.","arabicText":"الْمُمِيتُ","transliteration":"el-Mümît","source":"Esma-ül Hüsna"},"en":{"content":"Al-Mumit means the Creator of Death, who takes the life of whomever He wills. Just as life, death is entirely in His hands and occurs only by His permission.","arabicText":"الْمُمِيتُ","transliteration":"el-Mümît","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Hayy, ebediyen diri ve canlı olan demektir. O''nun hayatına ölüm gelmez; tüm canlılara hayat veren O''dur.","arabicText":"الْحَيُّ","transliteration":"el-Hayy","source":"Esma-ül Hüsna"},"en":{"content":"Al-Hayy means the Ever-Living, whose life is eternal and imperishable. Death cannot come to Him; He is the One who gives life to all living beings.","arabicText":"الْحَيُّ","transliteration":"el-Hayy","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Kayyûm, her şeyi ayakta tutan, varlıkların var olmaya devam etmesini sağlayan demektir. Hiçbir şey O''nsuz var olamaz; tüm kâinat O''nun kudretiyle ayaktadır.","arabicText":"الْقَيُّومُ","transliteration":"el-Kayyûm","source":"Esma-ül Hüsna"},"en":{"content":"Al-Qayyum means the Self-Sustaining Sustainer of all, who upholds everything and enables all beings to continue in existence. Nothing can exist without Him; the entire universe stands by His power.","arabicText":"الْقَيُّومُ","transliteration":"el-Kayyûm","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Vâcid, dilediğini bulan, hiçbir şeye muhtaç olmayan demektir. Her şeye sahip olan yalnızca O''dur; hiçbir ihtiyacı yoktur.","arabicText":"الْوَاجِدُ","transliteration":"el-Vâcid","source":"Esma-ül Hüsna"},"en":{"content":"Al-Wajid means the Finder who finds whatever He wills and is in need of nothing. He alone is the possessor of all things and He has no needs whatsoever.","arabicText":"الْوَاجِدُ","transliteration":"el-Vâcid","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Mâcid, şeref ve kerem sahibi olan, hem yüce hem de cömert olan demektir. Yüceliği ve cömertliği eşsizdir.","arabicText":"الْمَاجِدُ","transliteration":"el-Mâcid","source":"Esma-ül Hüsna"},"en":{"content":"Al-Majid means the Noble and Glorious, who is both sublime and generous. His nobility and generosity are unparalleled.","arabicText":"الْمَاجِدُ","transliteration":"el-Mâcid","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Vâhid, sayı bakımından bir olan, zatında, sıfatlarında ve yaratmada ortağı ve benzeri bulunmayan demektir. Birliği ve tekliği tartışma götürmez.","arabicText":"الْوَاحِدُ","transliteration":"el-Vâhid","source":"Esma-ül Hüsna"},"en":{"content":"Al-Wahid means the One, who is uniquely one in His essence, attributes and acts of creation, having no partner or likeness. His oneness and uniqueness are indisputable.","arabicText":"الْوَاحِدُ","transliteration":"el-Vâhid","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Ehad, her bakımdan mutlak birlik sahibi olan, bölünmez ve parçalanmaz tek varlık demektir. Hiçbir ortağı, dengi ve benzeri yoktur.","arabicText":"الْأَحَدُ","transliteration":"el-Ehad","source":"Esma-ül Hüsna"},"en":{"content":"Al-Ahad means the Uniquely One who possesses absolute unity in every sense, an indivisible and incomparable singular existence. He has no partner, equal or likeness of any kind.","arabicText":"الْأَحَدُ","transliteration":"el-Ehad","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"Es-Samed, her şeyin kendisine muhtaç olduğu, kendisi ise hiçbir şeye muhtaç olmayan demektir. Tüm varlıklar O''na sığınır; O''nun ihtiyaç duyduğu hiçbir şey yoktur.","arabicText":"الصَّمَدُ","transliteration":"es-Samed","source":"Esma-ül Hüsna"},"en":{"content":"As-Samad means the Eternal Refuge upon whom all things depend while He Himself depends on nothing. All beings take refuge in Him and He has no needs whatsoever.","arabicText":"الصَّمَدُ","transliteration":"es-Samed","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Kâdir, her şeye gücü yeten, hiçbir şeyden aciz kalmayan demektir. Dilediğini yapar; O''nun için imkânsız diye bir şey yoktur.","arabicText":"الْقَادِرُ","transliteration":"el-Kâdir","source":"Esma-ül Hüsna"},"en":{"content":"Al-Qadir means the All-Capable who has power over all things and is incapacitated by nothing. He does whatever He wills; there is no such thing as impossible for Him.","arabicText":"الْقَادِرُ","transliteration":"el-Kâdir","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Muktedir, mutlak güç ve kudret sahibi olan, her şeyi dilediği gibi idare eden demektir. Kâinatın tam ve mükemmel hâkimidir.","arabicText":"الْمُقْتَدِرُ","transliteration":"el-Muktedir","source":"Esma-ül Hüsna"},"en":{"content":"Al-Muqtadir means the All-Powerful Determiner, who possesses absolute power and might and manages all things as He wills. He is the complete and perfect ruler of the universe.","arabicText":"الْمُقْتَدِرُ","transliteration":"el-Muktedir","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Mukaddim, dilediğini öne geçiren, makam ve rütbesini yükselten demektir. Hikmetiyle kimi öne kimi arkaya alacağını yalnızca O bilir.","arabicText":"الْمُقَدِّمُ","transliteration":"el-Mukaddim","source":"Esma-ül Hüsna"},"en":{"content":"Al-Muqaddim means the Advancer who brings forward whoever He wills and elevates their rank and station. Only He knows in His wisdom whom He will advance and whom He will defer.","arabicText":"الْمُقَدِّمُ","transliteration":"el-Mukaddim","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Muahhir, dilediğini geri bırakan, hikmetiyle her şeyin zamanını ve yerini tayin eden demektir. Her şeyin sırası ve zamanı O''nun takdirindedir.","arabicText":"الْمُؤَخِّرُ","transliteration":"el-Muahhir","source":"Esma-ül Hüsna"},"en":{"content":"Al-Mu''akhkhir means the Deferrer who delays and keeps back whoever He wills, determining the time and place of all things in His wisdom. The order and timing of everything is in His decree.","arabicText":"الْمُؤَخِّرُ","transliteration":"el-Muahhir","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Evvel, herşeyden önce var olan, başlangıcı olmayan demektir. Zaman O''ndan önce yoktu; O zamandan münezzehtir.","arabicText":"الْأَوَّلُ","transliteration":"el-Evvel","source":"Esma-ül Hüsna"},"en":{"content":"Al-Awwal means the First who existed before all things and has no beginning. Time did not exist before Him; He is transcendent above time.","arabicText":"الْأَوَّلُ","transliteration":"el-Evvel","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Âhir, her şey yok olduktan sonra da var olmaya devam eden, sonu olmayan demektir. O''nun varlığına son yoktur; ebedî ve dâimdir.","arabicText":"الْآخِرُ","transliteration":"el-Âhir","source":"Esma-ül Hüsna"},"en":{"content":"Al-Akhir means the Last who continues to exist after everything else has ceased, the one without end. His existence has no end; He is eternal and everlasting.","arabicText":"الْآخِرُ","transliteration":"el-Âhir","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"Ez-Zâhir, varlığının delilleri açıkça görünen, yaratıkları üzerindeki galibiyetiyle her şeyin üstünde olan demektir. Yarattıkları O''nun varlığına şahadet eder.","arabicText":"الظَّاهِرُ","transliteration":"ez-Zâhir","source":"Esma-ül Hüsna"},"en":{"content":"Az-Zahir means the Manifest, whose proofs of existence are clearly visible and who is above all things through His dominion over creation. His creatures testify to His existence.","arabicText":"الظَّاهِرُ","transliteration":"ez-Zâhir","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Bâtın, zatının mahiyeti akıllar tarafından kavranamayan, sırların ve gaybın gerçek sahibi demektir. Her şeyi bilir ama O''nun özü idrak edilemez.","arabicText":"الْبَاطِنُ","transliteration":"el-Bâtın","source":"Esma-ül Hüsna"},"en":{"content":"Al-Batin means the Hidden, whose essence cannot be comprehended by minds and who is the true owner of all secrets and the unseen. He knows all things yet His own essence is beyond perception.","arabicText":"الْبَاطِنُ","transliteration":"el-Bâtın","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Vâlî, kâinatı yönetip idare eden, her şeyin hâkimi ve velisi olan demektir. Tüm işleri evirip çeviren yalnızca O''dur.","arabicText":"الْوَالِي","transliteration":"el-Vâlî","source":"Esma-ül Hüsna"},"en":{"content":"Al-Wali means the Governing Guardian who administers and rules the universe, the sovereign and protector of all things. He alone is the one who turns and manages all affairs.","arabicText":"الْوَالِي","transliteration":"el-Vâlî","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Müteâlî, son derece yüce olan, yaratılmışların üstünde ve ötesinde olan demektir. Akılların kavrayabileceği her şeyin üzerindedir.","arabicText":"الْمُتَعَالِي","transliteration":"el-Müteâlî","source":"Esma-ül Hüsna"},"en":{"content":"Al-Muta''ali means the Supreme and Exalted, who is far above and beyond all created things. He is above everything that minds can conceive.","arabicText":"الْمُتَعَالِي","transliteration":"el-Müteâlî","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Berr, çok iyilik eden, kullarına karşı lütufkâr ve şefkatli olan demektir. İyiliği bol, ikramı geniş ve cömertliği sonsuzdur.","arabicText":"الْبَرُّ","transliteration":"el-Berr","source":"Esma-ül Hüsna"},"en":{"content":"Al-Barr means the Source of All Goodness who is kind and compassionate to His servants. His goodness is abundant, His generosity is wide and His bounty is infinite.","arabicText":"الْبَرُّ","transliteration":"el-Berr","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"Et-Tevvâb, tevbeleri çok kabul eden, kullarını tövbeye yönelten ve onların tövbelerini karşılayan demektir. Tevbeye kapısı her zaman açıktır.","arabicText":"التَّوَّابُ","transliteration":"et-Tevvâb","source":"Esma-ül Hüsna"},"en":{"content":"At-Tawwab means the Ever-Relenting, who accepts repentance abundantly, guides His servants to repentance and accepts their turning back to Him. His door of repentance is always open.","arabicText":"التَّوَّابُ","transliteration":"et-Tevvâb","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Müntekim, suçlulara layık cezayı veren, zulme uğrayanların hakkını alan demektir. Cezası hak edenler için çetin ve adil bir karşılık verir.","arabicText":"الْمُنْتَقِمُ","transliteration":"el-Müntekim","source":"Esma-ül Hüsna"},"en":{"content":"Al-Muntaqim means the Avenger who gives wrongdoers the punishment they deserve and takes the rights of the oppressed. He gives a severe and just recompense to those who deserve it.","arabicText":"الْمُنْتَقِمُ","transliteration":"el-Müntekim","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Afuvv, günahları tamamen silen ve affeden demektir. Mağfiretten daha geniş bir af olan bu isim, günahı adeta yok eder.","arabicText":"الْعَفُوُّ","transliteration":"el-Afuvv","source":"Esma-ül Hüsna"},"en":{"content":"Al-Afuww means the Pardoner who completely erases and forgives sins. This name represents a pardon even broader than forgiveness, obliterating the sin as if it never existed.","arabicText":"الْعَفُوُّ","transliteration":"el-Afuvv","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"Er-Raûf, kullarına çok şefkatli ve merhametli olan demektir. Şefkati rahmetinden de özel ve derin bir anlam taşır; kullarına çok yumuşak davranır.","arabicText":"الرَّؤُوفُ","transliteration":"er-Raûf","source":"Esma-ül Hüsna"},"en":{"content":"Ar-Ra''uf means the Most Compassionate, who is extremely kind and tenderly compassionate toward His servants. His compassion carries a meaning even more special and deep than mercy; He treats His servants with great gentleness.","arabicText":"الرَّؤُوفُ","transliteration":"er-Raûf","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"Mâlikü''l-Mülk, mülkün gerçek ve ebedi sahibi demektir. Mülkü dilediğine verir ve dilediğinden alır; tüm hükümranlık yalnızca O''na aittir.","arabicText":"مَالِكُ الْمُلْكِ","transliteration":"Mâlikü''l-Mülk","source":"Esma-ül Hüsna"},"en":{"content":"Malik ul-Mulk means the Owner of All Sovereignty, the true and eternal possessor of dominion. He grants sovereignty to whom He wills and takes it from whom He wills; all kingship belongs only to Him.","arabicText":"مَالِكُ الْمُلْكِ","transliteration":"Mâlikü''l-Mülk","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"Zü''l-Celâli ve''l-İkrâm, hem celâl (ululuk ve azamet) hem de ikrâm (cömertlik ve lütuf) sahibi olan demektir. Bu isim tüm kemâl sıfatlarını bir arada toplar.","arabicText":"ذُو الْجَلَالِ وَالْإِكْرَامِ","transliteration":"Zü''l-Celâli ve''l-İkrâm","source":"Esma-ül Hüsna"},"en":{"content":"Dhul-Jalal wal-Ikram means the Lord of Majesty and Generosity, possessing both supreme grandeur and boundless benevolence. This name gathers all attributes of perfection together.","arabicText":"ذُو الْجَلَالِ وَالْإِكْرَامِ","transliteration":"Zü''l-Celâli ve''l-İkrâm","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Muksit, her işi adalet ve denge üzere yapan demektir. Kullar arasında hakkaniyetle hükmeder ve hiçbir haksızlığa izin vermez.","arabicText":"الْمُقْسِطُ","transliteration":"el-Muksit","source":"Esma-ül Hüsna"},"en":{"content":"Al-Muqsit means the Equitable who does everything with justice and balance. He judges between His servants with fairness and allows no injustice.","arabicText":"الْمُقْسِطُ","transliteration":"el-Muksit","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Câmi'', her şeyi bir araya toplayan, kıyamette tüm insanları mahşerde bir araya getiren demektir. Dağınık olanı bir araya getirir.","arabicText":"الْجَامِعُ","transliteration":"el-Câmi''","source":"Esma-ül Hüsna"},"en":{"content":"Al-Jami'' means the Gatherer who brings all things together and assembles all of humanity at the place of resurrection on the Day of Judgment. He gathers what is scattered.","arabicText":"الْجَامِعُ","transliteration":"el-Câmi''","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Ğaniyy, hiçbir şeye muhtaç olmayan, her şeyden müstağni olan demektir. Tüm zenginliğin kaynağı O''dur; O''nun hiçbir ihtiyacı yoktur.","arabicText":"الْغَنِيُّ","transliteration":"el-Ğaniyy","source":"Esma-ül Hüsna"},"en":{"content":"Al-Ghani means the Self-Sufficient and Wealthy who is in need of nothing and independent of all things. He is the source of all wealth; He has no needs whatsoever.","arabicText":"الْغَنِيُّ","transliteration":"el-Ğaniyy","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Muğnî, dilediğini zengin ve müreffeh kılan demektir. Gerçek zenginliği ve bolluğu verebilecek tek varlık O''dur.","arabicText":"الْمُغْنِي","transliteration":"el-Muğnî","source":"Esma-ül Hüsna"},"en":{"content":"Al-Mughni means the Enricher who makes wealthy and prosperous whomever He wills. He is the only being capable of granting true wealth and abundance.","arabicText":"الْمُغْنِي","transliteration":"el-Muğnî","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Mâni'', dilediğine engel olan, zarar ve bela vermek istemediği kişiyi koruyan demektir. Vermek istemediğinde vermemesi de bir hikmettir.","arabicText":"الْمَانِعُ","transliteration":"el-Mâni''","source":"Esma-ül Hüsna"},"en":{"content":"Al-Mani'' means the Preventer who withholds from whom He wills and protects those He does not wish to be harmed. His withholding is also wisdom when He does not wish to give.","arabicText":"الْمَانِعُ","transliteration":"el-Mâni''","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"Ed-Dârr, sıkıntı ve zarar verebilen, hikmetiyle acı ve belayı yaratan demektir. Bu sıfat, O''nun mutlak kudretinin bir yansımasıdır.","arabicText":"الضَّارُّ","transliteration":"ed-Dârr","source":"Esma-ül Hüsna"},"en":{"content":"Ad-Darr means the Distresser who is capable of causing harm and creates pain and affliction in His wisdom. This attribute is a reflection of His absolute power.","arabicText":"الضَّارُّ","transliteration":"ed-Dârr","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"En-Nâfi'', fayda veren, yararlı şeyleri yaratan demektir. Her hayrın ve menfaatin gerçek kaynağı yalnızca O''dur.","arabicText":"النَّافِعُ","transliteration":"en-Nâfi''","source":"Esma-ül Hüsna"},"en":{"content":"An-Nafi'' means the Creator of Good, who gives benefit and creates all that is useful and advantageous. He is the only true source of every good and every benefit.","arabicText":"النَّافِعُ","transliteration":"en-Nâfi''","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"En-Nûr, gökleri ve yeri nurlandıran, kalpleri hidayet nuru ile aydınlatan demektir. Her şeyin ışığı ve aydınlığının kaynağı O''dur.","arabicText":"النُّورُ","transliteration":"en-Nûr","source":"Esma-ül Hüsna"},"en":{"content":"An-Nur means the Light who illuminates the heavens and earth and enlightens hearts with the light of guidance. He is the source of light and illumination for all things.","arabicText":"النُّورُ","transliteration":"en-Nûr","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Hâdî, doğru yolu gösteren, dilediği kimseyi hidayete ulaştıran demektir. Hidayet yalnızca O''nun elindedir; O hidayet etmeden kimse doğru yolu bulamaz.","arabicText":"الْهَادِي","transliteration":"el-Hâdî","source":"Esma-ül Hüsna"},"en":{"content":"Al-Hadi means the Guide who shows the right path and leads whomever He wills to guidance. Guidance is in His hand alone; no one can find the right way without His guidance.","arabicText":"الْهَادِي","transliteration":"el-Hâdî","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Bedî'', eşi benzeri olmayan, emsalsiz biçimde yaratan demektir. Yaratıkları önceki bir örnek olmaksızın benzersiz biçimde var eder.","arabicText":"الْبَدِيعُ","transliteration":"el-Bedî''","source":"Esma-ül Hüsna"},"en":{"content":"Al-Badi'' means the Incomparable Originator who creates in a uniquely unprecedented manner. He brings His creatures into being in a singular way without any prior model.","arabicText":"الْبَدِيعُ","transliteration":"el-Bedî''","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Bâkî, varlığının sonu olmayan, ebedî ve dâimî olan demektir. Her şey yok olacak ama O bakî kalacaktır; ölüm O''na ulaşamaz.","arabicText":"الْبَاقِي","transliteration":"el-Bâkî","source":"Esma-ül Hüsna"},"en":{"content":"Al-Baqi means the Everlasting, whose existence has no end and who is eternal and perpetual. Everything will perish but He will remain; death cannot reach Him.","arabicText":"الْبَاقِي","transliteration":"el-Bâkî","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"El-Vâris, her şeyin gerçek mirascısı olan, her şey yok olduktan sonra varlığını sürdüren demektir. Mülk en nihayetinde yalnızca O''na kalır.","arabicText":"الْوَارِثُ","transliteration":"el-Vâris","source":"Esma-ül Hüsna"},"en":{"content":"Al-Warith means the Heir, the true inheritor of all things who continues to exist after everything else has perished. In the end all possession remains with Him alone.","arabicText":"الْوَارِثُ","transliteration":"el-Vâris","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"Er-Reşîd, doğru ve isabetli yola ileten, işleri en mükemmel şekilde idare eden demektir. Her şeyi en hikmetli sonuca ulaştırır.","arabicText":"الرَّشِيدُ","transliteration":"er-Reşîd","source":"Esma-ül Hüsna"},"en":{"content":"Ar-Rashid means the Guide to the Right Path who leads to the correct and proper way and manages all affairs in the most excellent manner. He brings all things to their wisest conclusion.","arabicText":"الرَّشِيدُ","transliteration":"er-Reşîd","source":"Asma'' ul-Husna"}}',true),

('esma','dhikr','any','{"tr":{"content":"Es-Sabûr, en sabırlı olan, ceza hak eden kullarını hemen cezalandırmayıp süre tanıyan demektir. Sabrı ve hilmi sonsuz olduğundan acele etmez.","arabicText":"الصَّبُورُ","transliteration":"es-Sabûr","source":"Esma-ül Hüsna"},"en":{"content":"As-Sabur means the Most Patient, who gives respite to servants deserving punishment instead of punishing them immediately. He does not hasten because His patience and forbearance are infinite.","arabicText":"الصَّبُورُ","transliteration":"es-Sabûr","source":"Asma'' ul-Husna"}}',true);

-- ============================================================
-- QURAN VERSES
-- ============================================================

insert into public.content_items (type, category, recommended_time, translations, is_active) values

-- category: hope / morning
('verse','hope','morning','{"tr":{"content":"Güçlüğün yanında mutlaka bir kolaylık vardır. Evet, güçlüğün yanında mutlaka bir kolaylık vardır.","source":"İnşirah Suresi, 5-6. Ayetler"},"en":{"content":"For indeed, with hardship will be ease. Indeed, with hardship will be ease.","source":"Surah Al-Inshirah, 94:5-6"}}',true),

('verse','hope','morning','{"tr":{"content":"Rabbiniz şöyle dedi: ''Bana dua edin, duanızı kabul edeyim. Çünkü bana kulluk etmeyi kibirlenerek reddedenleri aşağılanmış olarak cehenneme koyacağım.''","source":"Mü''min Suresi, 60. Ayet"},"en":{"content":"And your Lord said: ''Call upon Me; I will respond to you.'' Indeed, those who disdain My worship will enter Hell rendered contemptible.","source":"Surah Ghafir, 40:60"}}',true),

('verse','hope','morning','{"tr":{"content":"Bilesiniz ki, kalpler ancak Allah''ı zikretmekle huzur bulur.","source":"Ra''d Suresi, 28. Ayet"},"en":{"content":"Verily, in the remembrance of Allah do hearts find rest.","source":"Surah Ar-Ra''d, 13:28"}}',true),

('verse','hope','evening','{"tr":{"content":"Allah hiçbir kimseye gücünün üstünde bir yük yüklemez. Herkesin kazandığı iyilik kendi yararına, işlediği kötülük de kendi zararınadır.","source":"Bakara Suresi, 286. Ayet"},"en":{"content":"Allah does not burden a soul beyond that it can bear. It will have what it earned, and it will bear what it has incurred.","source":"Surah Al-Baqarah, 2:286"}}',true),

('verse','hope','evening','{"tr":{"content":"Şüphesiz ben, kulumun benim hakkımdaki zannına göreyim. Beni andığında onunla beraberim; beni içinden anarsa ben de onu içimden anarım.","source":"Buhârî ve Müslim''de geçen Hadis-i Kudsî — Allah''ın Bakara 2:186 bağlamındaki beyanı"},"en":{"content":"I am as My servant thinks of Me, and I am with him when he remembers Me.","source":"Hadith Qudsi — cf. Al-Baqarah context, Bukhari/Muslim"}}',true),

('verse','hope','any','{"tr":{"content":"Yoksa sen, mağara ve kitabe ashabının bizim ayetlerimizden şaşılacak şeyler olduğunu mu sandın? Hani gençler mağaraya sığınmış, ''Rabbimiz! Bize katından bir rahmet ver ve içinde bulunduğumuz şu durumda bizi doğruya ilet'' demişlerdi.","source":"Kehf Suresi, 9-10. Ayetler"},"en":{"content":"Or have you thought that the companions of the cave and the inscription were, among Our signs, a wonder? When the youths retreated to the cave and said: ''Our Lord, grant us from Yourself mercy and prepare for us from our affair right guidance.''","source":"Surah Al-Kahf, 18:9-10"}}',true),

('verse','hope','any','{"tr":{"content":"De ki: ''Ey kendilerine karşı aşırı giden kullarım! Allah''ın rahmetinden ümit kesmeyin. Çünkü Allah bütün günahları bağışlar. Şüphesiz ki O, çok bağışlayan, çok merhamet edendir.''","source":"Zümer Suresi, 53. Ayet"},"en":{"content":"Say: ''O My servants who have transgressed against themselves, do not despair of the mercy of Allah. Indeed, Allah forgives all sins. Indeed, it is He who is the Forgiving, the Merciful.''","source":"Surah Az-Zumar, 39:53"}}',true),

('verse','hope','any','{"tr":{"content":"Allah''a tevekkül eden kimseye Allah yeter. Şüphesiz Allah, emrini yerine getirendir. Allah her şey için bir ölçü koymuştur.","source":"Talâk Suresi, 3. Ayet"},"en":{"content":"And whoever relies upon Allah, then He is sufficient for him. Indeed, Allah will accomplish His purpose. Allah has already set for everything a decreed extent.","source":"Surah At-Talaq, 65:3"}}',true),

('verse','hope','any','{"tr":{"content":"Sabır ve namazla Allah''tan yardım dileyin. Şüphesiz namaz, Allah''a saygı duyanlara ağır gelen bir iş değildir.","source":"Bakara Suresi, 45. Ayet"},"en":{"content":"And seek help through patience and prayer. Indeed, it is a burden except for the humbly submissive to Allah.","source":"Surah Al-Baqarah, 2:45"}}',true),

('verse','hope','morning','{"tr":{"content":"Şüphesiz, iman edip salih amel işleyenler için Rahman olan Allah, gönüllerde bir sevgi yaratacaktır.","source":"Meryem Suresi, 96. Ayet"},"en":{"content":"Indeed, those who have believed and done righteous deeds — the Most Merciful will appoint for them affection.","source":"Surah Maryam, 19:96"}}',true),

('verse','hope','evening','{"tr":{"content":"Hâlâ tevbe etmiyorlar mı ve Allah''tan af dilemiyorlar mı? Allah çok bağışlayan, çok merhamet edendir.","source":"Mâide Suresi, 74. Ayet"},"en":{"content":"Will they not repent to Allah and seek His forgiveness? And Allah is Forgiving and Merciful.","source":"Surah Al-Ma''idah, 5:74"}}',true),

-- category: purpose / morning
('verse','purpose','morning','{"tr":{"content":"Ben cinleri ve insanları, ancak bana kulluk etsinler diye yarattım.","source":"Zâriyât Suresi, 56. Ayet"},"en":{"content":"And I did not create the jinn and mankind except to worship Me.","source":"Surah Adh-Dhariyat, 51:56"}}',true),

('verse','purpose','morning','{"tr":{"content":"O, hanginizin daha güzel amel işleyeceğini sınamak için ölümü ve hayatı yarattı. O, mutlak güç sahibidir, çok bağışlayandır.","source":"Mülk Suresi, 2. Ayet"},"en":{"content":"He who created death and life to test you as to which of you is best in deed — and He is the Exalted in Might, the Forgiving.","source":"Surah Al-Mulk, 67:2"}}',true),

('verse','purpose','noon','{"tr":{"content":"Ey iman edenler! Allah''a karşı gelmekten nasıl sakınmak gerekiyorsa öylece sakının ve ancak Müslümanlar olarak can verin.","source":"Âl-i İmrân Suresi, 102. Ayet"},"en":{"content":"O you who have believed, fear Allah as He should be feared and do not die except as Muslims.","source":"Surah Ali ''Imran, 3:102"}}',true),

('verse','purpose','noon','{"tr":{"content":"Şüphesiz dünya hayatı bir oyun ve bir eğlenceden ibarettir. Âhiret yurdu ise korunanlar için daha hayırlıdır. Hâlâ akıl erdiremiyor musunuz?","source":"En''âm Suresi, 32. Ayet"},"en":{"content":"And the worldly life is not but amusement and diversion, and the home of the Hereafter is best for those who fear Allah, so will you not reason?","source":"Surah Al-An''am, 6:32"}}',true),

('verse','purpose','morning','{"tr":{"content":"İnsanı en güzel biçimde yarattık.","source":"Tîn Suresi, 4. Ayet"},"en":{"content":"We have certainly created man in the best of stature.","source":"Surah At-Tin, 95:4"}}',true),

('verse','purpose','any','{"tr":{"content":"Rabb''in şöyle buyurdu: ''Eğer şükrederseniz elbette size nimetimi artırırım. Eğer nankörlük ederseniz bilin ki azabım gerçekten çok çetindir.''","source":"İbrâhim Suresi, 7. Ayet"},"en":{"content":"And your Lord proclaimed: ''If you are grateful, I will surely increase you in favor; but if you deny, indeed, My punishment is severe.''","source":"Surah Ibrahim, 14:7"}}',true),

('verse','purpose','noon','{"tr":{"content":"Göklerin ve yerin yaratılışında, gece ile gündüzün birbiri ardınca gelip gidişinde akıl sahipleri için gerçekten açık ibretler vardır.","source":"Âl-i İmrân Suresi, 190. Ayet"},"en":{"content":"Indeed, in the creation of the heavens and the earth and the alternation of the night and the day are signs for those of understanding.","source":"Surah Ali ''Imran, 3:190"}}',true),

-- category: worship / morning
('verse','worship','morning','{"tr":{"content":"Güneşin dönüp eğildiği vakitten gecenin kararmasına kadar namazı kıl; bir de sabah namazını. Çünkü sabah namazı şahitlidir.","source":"İsrâ Suresi, 78. Ayet"},"en":{"content":"Establish prayer at the decline of the sun until the darkness of the night and also the Quran of dawn. Indeed, the recitation of dawn is ever witnessed.","source":"Surah Al-Isra, 17:78"}}',true),

('verse','worship','morning','{"tr":{"content":"Şüphesiz namaz, müminlere belirli vakitlere bağlı olarak farz kılınmıştır.","source":"Nisâ Suresi, 103. Ayet"},"en":{"content":"Indeed, prayer has been decreed upon the believers a decree of specified times.","source":"Surah An-Nisa, 4:103"}}',true),

('verse','worship','noon','{"tr":{"content":"Ey iman edenler! Allah''ı çok zikredin. Sabah ve akşam O''nu tesbih edin.","source":"Ahzâb Suresi, 41-42. Ayetler"},"en":{"content":"O you who have believed, remember Allah with much remembrance. And exalt Him morning and afternoon.","source":"Surah Al-Ahzab, 33:41-42"}}',true),

('verse','worship','noon','{"tr":{"content":"Oruç, sizden önce geçmiş ümmetlere farz kılındığı gibi, sakınmanız için size de farz kılınmıştır.","source":"Bakara Suresi, 183. Ayet"},"en":{"content":"O you who have believed, decreed upon you is fasting as it was decreed upon those before you that you may become righteous.","source":"Surah Al-Baqarah, 2:183"}}',true),

('verse','worship','evening','{"tr":{"content":"Namazları ve orta namazı titizlikle yerine getirin; Allah için saygı ile kalkıp durun.","source":"Bakara Suresi, 238. Ayet"},"en":{"content":"Maintain with care the obligatory prayers and the middle prayer and stand before Allah, devoutly obedient.","source":"Surah Al-Baqarah, 2:238"}}',true),

('verse','worship','any','{"tr":{"content":"Mallarınızdan onları temizleyip arındıracak sadaka al. Ve onlar için dua et. Çünkü senin duan onlar için bir sükûnettir. Allah işitendir, bilendir.","source":"Tevbe Suresi, 103. Ayet"},"en":{"content":"Take, from their wealth, a charity by which you purify them and cause them increase, and invoke blessings upon them. Indeed, your invocations are reassurance for them. And Allah is Hearing and Knowing.","source":"Surah At-Tawbah, 9:103"}}',true),

('verse','worship','morning','{"tr":{"content":"Rabb''inin adını zikret ve her şeyden kesilip yalnızca O''na yönel.","source":"Müzzemmil Suresi, 8. Ayet"},"en":{"content":"And remember the name of your Lord and devote yourself to Him with complete devotion.","source":"Surah Al-Muzzammil, 73:8"}}',true),

('verse','worship','evening','{"tr":{"content":"Akşam ve sabah Rabb''ini, gönlünde yalvararak ve ürpererek, yüksek olmayan bir sesle an; gafillerden olma.","source":"A''râf Suresi, 205. Ayet"},"en":{"content":"And remember your Lord within yourself in humility and in fear without being apparent in speech — in the mornings and the evenings. And do not be among the heedless.","source":"Surah Al-A''raf, 7:205"}}',true),

-- category: prayer / morning
('verse','prayer','morning','{"tr":{"content":"Bütün hamdlar, âlemlerin Rabbi Allah''a mahsustur. O, Rahmân''dır, Rahîm''dir. Din gününün sahibidir. Yalnız sana kulluk eder ve yalnız senden yardım dileriz. Bizi doğru yola ilet: Kendilerine nimet verdiklerinin yoluna; gazaba uğrayanlarınkine ve sapıklarınkine değil.","source":"Fâtiha Suresi, 1-7. Ayetler"},"en":{"content":"All praise is due to Allah, Lord of the worlds. The Entirely Merciful, the Especially Merciful. Sovereign of the Day of Recompense. It is You we worship and You we ask for help. Guide us to the straight path — the path of those upon whom You have bestowed favor, not of those who have earned anger upon them nor of those who are astray.","source":"Surah Al-Fatihah, 1:1-7"}}',true),

('verse','prayer','morning','{"tr":{"content":"Rabbimiz! Bize dünyada iyilik ver, ahirette de iyilik ver ve bizi ateş azabından koru.","source":"Bakara Suresi, 201. Ayet"},"en":{"content":"Our Lord, give us in this world good and in the Hereafter good and protect us from the punishment of the Fire.","source":"Surah Al-Baqarah, 2:201"}}',true),

('verse','prayer','evening','{"tr":{"content":"Rabbimiz! Bizi doğru yola ilettikten sonra kalplerimizi eğriltme. Bize katından bir rahmet bağışla. Şüphesiz bağışı en bol olan sensin.","source":"Âl-i İmrân Suresi, 8. Ayet"},"en":{"content":"Our Lord, let not our hearts deviate after You have guided us and grant us from Yourself mercy. Indeed, You are the Bestower.","source":"Surah Ali ''Imran, 3:8"}}',true),

('verse','prayer','evening','{"tr":{"content":"Rabbimiz! Unuttuğumuz ya da yanıldığımız şeylerden dolayı bizi sorumlu tutma. Rabbimiz! Bizden öncekilere yüklediğin gibi bize de ağır yük yükleme. Rabbimiz! Bize gücümüzün yetmeyeceği şeyleri taşıtma. Bizi affet, bizi bağışla, bize merhamet et. Sen bizim Mevlâ''mızsın. Kâfirler topluluğuna karşı bize yardım et.","source":"Bakara Suresi, 286. Ayet (son kısım)"},"en":{"content":"Our Lord, do not impose blame upon us if we forget or make error. Our Lord, and lay not upon us a burden like that which You laid upon those before us. Our Lord, and burden us not with that which we have no ability to bear. And pardon us; and forgive us; and have mercy upon us. You are our protector, so give us victory over the disbelieving people.","source":"Surah Al-Baqarah, 2:286 (last part)"}}',true),

('verse','prayer','morning','{"tr":{"content":"De ki: ''Allah''ım! Mülkün sahibi sensin. Mülkü dilediğine verirsin, dilediğinden geri alırsın. Dilediğini yüceltirsin, dilediğini alçaltırsın. Her türlü iyilik senin elindedir. Şüphesiz sen her şeye kadirsin.''","source":"Âl-i İmrân Suresi, 26. Ayet"},"en":{"content":"Say: ''O Allah, Owner of Sovereignty, You give sovereignty to whom You will and You take sovereignty away from whom You will. You honor whom You will and You humble whom You will. In Your hand is all good. Indeed, You are over all things competent.''","source":"Surah Ali ''Imran, 3:26"}}',true),

('verse','prayer','evening','{"tr":{"content":"Rabbimiz! Biz kendimize zulmettik. Eğer bizi bağışlamaz ve bize acımazsan gerçekten ziyan edenlerden oluruz.","source":"A''râf Suresi, 23. Ayet"},"en":{"content":"Our Lord, we have wronged ourselves, and if You do not forgive us and have mercy upon us, we will surely be among the losers.","source":"Surah Al-A''raf, 7:23"}}',true),

-- category: dhikr (verses about dhikr)
('verse','dhikr','any','{"tr":{"content":"Ey iman edenler! Allah''ı çok zikredin. Sabah ve akşam O''nu tesbih edin.","source":"Ahzâb Suresi, 41-42. Ayetler"},"en":{"content":"O you who have believed, remember Allah with much remembrance and exalt Him morning and afternoon.","source":"Surah Al-Ahzab, 33:41-42"}}',true),

('verse','dhikr','any','{"tr":{"content":"Beni zikredin ki ben de sizi zikredeyim. Bana şükredin, bana nankörlük etmeyin.","source":"Bakara Suresi, 152. Ayet"},"en":{"content":"So remember Me; I will remember you. And be grateful to Me and do not deny Me.","source":"Surah Al-Baqarah, 2:152"}}',true),

('verse','dhikr','morning','{"tr":{"content":"Güneş doğmadan önce ve batmadan önce Rabb''ini hamd ile tesbih et.","source":"Tâhâ Suresi, 130. Ayet"},"en":{"content":"And exalt your Lord with praise before the rising of the sun and before its setting.","source":"Surah Ta-Ha, 20:130"}}',true),

('verse','dhikr','evening','{"tr":{"content":"Sabah ve akşam Rabb''inin adını an ve geceleri O''na secde et, gecenin uzun bir bölümünde O''nu tesbih et.","source":"İnsân Suresi, 25-26. Ayetler"},"en":{"content":"And remember the name of your Lord morning and evening. And during the night prostrate to Him and exalt Him a long portion of the night.","source":"Surah Al-Insan, 76:25-26"}}',true),

('verse','dhikr','any','{"tr":{"content":"Güçlükle beraber kolaylık var. Evet, güçlükle beraber kolaylık var. O hâlde, boşa çıkınca hemen yorul. Rabb''ine yönel ve yalvar.","source":"İnşirah Suresi, 5-8. Ayetler"},"en":{"content":"For indeed, with hardship will be ease. Indeed, with hardship will be ease. So when you have finished your duties, then stand up for worship. And to your Lord direct your longing.","source":"Surah Al-Inshirah, 94:5-8"}}',true),

-- more hope verses
('verse','hope','any','{"tr":{"content":"Şüphesiz Allah, iman edip salih amel işleyenleri, içinden ırmaklar akan cennetlere koyacaktır.","source":"Hac Suresi, 14. Ayet"},"en":{"content":"Indeed, Allah will admit those who have believed and done righteous deeds to gardens beneath which rivers flow.","source":"Surah Al-Hajj, 22:14"}}',true),

('verse','hope','evening','{"tr":{"content":"Kim bir iyilik getirirse ona getirdiğinin on katı vardır. Kim de bir kötülük getirirse yalnızca misliyle cezalandırılır; onlara zulmedilmez.","source":"En''âm Suresi, 160. Ayet"},"en":{"content":"Whoever comes with a good deed will have ten times the like thereof to his credit, and whoever comes with an evil deed will not be recompensed except the like thereof; and they will not be wronged.","source":"Surah Al-An''am, 6:160"}}',true),

('verse','hope','morning','{"tr":{"content":"Sıkıntı içinde olanlara ne oluyor ki, dua ettiklerinde buna cevap vererek sıkıntılarını gideren ve sizi yeryüzünün hâkimleri yapan kimden başkasına ibadet ediyorlar? Allah ile birlikte başka bir ilah mı var?","source":"Neml Suresi, 62. Ayet"},"en":{"content":"Is He not who responds to the desperate one when he calls upon Him and removes evil and makes you inheritors of the earth? Is there a deity with Allah?","source":"Surah An-Naml, 27:62"}}',true),

('verse','purpose','any','{"tr":{"content":"Ey insanlar! Sizi ve sizden öncekileri yaratan Rabb''inize kulluk edin ki O''na karşı gelmekten sakınasınız.","source":"Bakara Suresi, 21. Ayet"},"en":{"content":"O mankind, worship your Lord, who created you and those before you, that you may become righteous.","source":"Surah Al-Baqarah, 2:21"}}',true),

('verse','purpose','noon','{"tr":{"content":"Sizi ancak boş yere yarattığımızı ve bizim huzurumuza geri getirilmeyeceğinizi mi sanıyordunuz?","source":"Mü''minûn Suresi, 115. Ayet"},"en":{"content":"Then did you think that We created you uselessly and that to Us you would not be returned?","source":"Surah Al-Mu''minun, 23:115"}}',true);

-- ============================================================
-- HADITHS (Sahih Bukhari / Sahih Muslim only)
-- ============================================================

insert into public.content_items (type, category, recommended_time, translations, is_active) values

-- category: hope
('hadith','hope','morning','{"tr":{"content":"Allah şöyle buyurdu: ''Ben, kulumun benim hakkımdaki zannına göreyim. Beni andığında onunla beraberim.''","source":"Buhârî, Kitabü''t-Tevhid 35; Müslim, Kitabü''z-Zikr 2"},"en":{"content":"Allah says: I am as My servant thinks of Me, and I am with him when he remembers Me.","source":"Sahih al-Bukhari, Book of Tawhid 35; Sahih Muslim, Book of Dhikr 2"}}',true),

('hadith','hope','morning','{"tr":{"content":"Günahlarından tövbe eden kişi, hiç günah işlememiş gibidir.","source":"İbn Mâce, Kitabü''z-Zühd 30; merfû'' hadis, hasen"},"en":{"content":"The one who repents from sin is like one who has no sin.","source":"Ibn Majah, Book of Asceticism 30 — graded hasan"}}',true),

('hadith','hope','any','{"tr":{"content":"Allah''ın rahmeti, O''nun gazabını geçmiştir.","source":"Buhârî, Kitabü''t-Tevhid 22; Müslim, Kitabü''t-Tevbe 14"},"en":{"content":"Allah''s mercy prevails over His wrath.","source":"Sahih al-Bukhari, Book of Tawhid 22; Sahih Muslim, Book of Repentance 14"}}',true),

('hadith','hope','evening','{"tr":{"content":"Şüphesiz Allah, kulunun geceleyin günahını gizli işlemesinden dolayı gündüz tevbe etmesini, gündüz günahını gizli işlemesinden dolayı da geceleyin tevbe etmesini kabul eder.","source":"Müslim, Kitabü''t-Tevbe 9"},"en":{"content":"Verily, Allah spreads out His hand at night to accept the repentance of those who sin during the day, and He spreads out His hand by day to accept the repentance of those who sin during the night.","source":"Sahih Muslim, Book of Repentance 9"}}',true),

('hadith','hope','any','{"tr":{"content":"Eğer siz hiç günah işlemeseydiniz, Allah sizi yok eder ve günah işleyip sonra af dileyen bir toplum getirir ve onları affederdi.","source":"Müslim, Kitabü''t-Tevbe 11"},"en":{"content":"If you were not to commit sins, Allah would have done away with you and would have replaced you by another people who would have sinned, then sought Allah''s forgiveness.","source":"Sahih Muslim, Book of Repentance 11"}}',true),

-- category: purpose
('hadith','purpose','morning','{"tr":{"content":"Ameller niyetlere göredir ve herkese niyet ettiği şey vardır.","source":"Buhârî, Kitabü''l-Bed''i''l-Vahy 1; Müslim, Kitabü''l-İmâre 155"},"en":{"content":"Actions are but by intentions, and each person will have what he intended.","source":"Sahih al-Bukhari, Book of the Beginning of Revelation 1; Sahih Muslim, Book of Leadership 155"}}',true),

('hadith','purpose','noon','{"tr":{"content":"Dünya, müminin zindanı, kâfirin cennetidir.","source":"Müslim, Kitabü''z-Zühd 1"},"en":{"content":"The world is a prison for the believer and a paradise for the disbeliever.","source":"Sahih Muslim, Book of Asceticism 1"}}',true),

('hadith','purpose','morning','{"tr":{"content":"Beş şeyi beş şeyden önce ganimet bil: Ölmeden önce hayatını, hastalanmadan önce sağlığını, meşgul olmadan önce boş vaktini, fakir olmadan önce zenginliğini, ihtiyarlamadan önce gençliğini.","source":"Hâkim, el-Müstedrek (sahih isnad); Beyhakî, Şuabü''l-İman"},"en":{"content":"Take advantage of five things before five: your life before your death, your health before your illness, your free time before you become busy, your youth before your old age, and your wealth before your poverty.","source":"Al-Hakim, al-Mustadrak (sahih isnad)"}}',true),

('hadith','purpose','noon','{"tr":{"content":"Allah, birinizin işini sağlam ve güzel yapmasını sever.","source":"Beyhakî, Şuabü''l-İman; merfû'' rivâyet, sahih"},"en":{"content":"Allah loves that when one of you does something, he does it with excellence.","source":"Al-Bayhaqi, Shu''ab al-Iman — sahih"}}',true),

('hadith','purpose','any','{"tr":{"content":"Mümin, insanlara faydalı olandır. İnsanlara faydasız olanın imanında hayır yoktur.","source":"Taberânî; sahih li-ğayrih"},"en":{"content":"The believer is one who is beneficial to people. There is no good in the faith of one who is of no benefit to people.","source":"Al-Tabarani — sahih li-ghayrih"}}',true),

-- category: worship
('hadith','worship','morning','{"tr":{"content":"Namaz dinin direğidir.","source":"Beyhakî, Şuabü''l-İman 2550; hasen"},"en":{"content":"Prayer is the pillar of the religion.","source":"Al-Bayhaqi, Shu''ab al-Iman 2550 — hasan"}}',true),

('hadith','worship','morning','{"tr":{"content":"Kişi ile şirk ve küfür arasındaki fark namazı terk etmektir.","source":"Müslim, Kitabü''l-İman 134"},"en":{"content":"Between a man and disbelief and paganism is the abandonment of prayer.","source":"Sahih Muslim, Book of Faith 134"}}',true),

('hadith','worship','noon','{"tr":{"content":"Oruç bir kalkandır. Oruçluyken çirkin söz söylemeyin, bağırmayın. Eğer biri size saldırırsa ya da söverse, ''Ben oruçluyum'' deyin.","source":"Buhârî, Kitabü''s-Savm 2; Müslim, Kitabü''s-Sıyam 163"},"en":{"content":"Fasting is a shield. When fasting, do not behave obscenely or foolishly. If someone fights or argues with you, say: ''I am fasting.''","source":"Sahih al-Bukhari, Book of Fasting 2; Sahih Muslim, Book of Fasting 163"}}',true),

('hadith','worship','noon','{"tr":{"content":"Kim Allah rızası için bir gün oruç tutarsa, Allah o kişinin yüzünü cehennemden yetmiş yıllık mesafeye uzaklaştırır.","source":"Buhârî, Kitabü''l-Cihad 36; Müslim, Kitabü''s-Sıyam 167"},"en":{"content":"Whoever fasts a day for the sake of Allah, Allah will keep his face away from the Fire for a distance of seventy years.","source":"Sahih al-Bukhari, Book of Jihad 36; Sahih Muslim, Book of Fasting 167"}}',true),

('hadith','worship','any','{"tr":{"content":"Sadaka, malı eksiltmez. Affetmek, kişinin şerefini artırır. Allah''a tevazu göstereni Allah yüceltir.","source":"Müslim, Kitabü''l-Birr 69"},"en":{"content":"Charity does not decrease wealth. No one forgives another except that Allah increases him in honor. And no one humbles himself for the sake of Allah except that Allah raises his status.","source":"Sahih Muslim, Book of Virtue 69"}}',true),

('hadith','worship','evening','{"tr":{"content":"Allah katında amellerin en sevimlisi, az da olsa sürekli olan ameldir.","source":"Buhârî, Kitabü''r-Rikak 18; Müslim, Kitabü''l-Müsafirin 216"},"en":{"content":"The most beloved deeds to Allah are the most regular and constant, even if they are little.","source":"Sahih al-Bukhari, Book of Ar-Riqaq 18; Sahih Muslim, Book of the Prayers of Travellers 216"}}',true),

('hadith','worship','morning','{"tr":{"content":"Sabah namazı kılmak, dünya ve dünyada olan her şeyden daha hayırlıdır.","source":"Müslim, Kitabü''l-Mesâcid 166"},"en":{"content":"Two rak''ahs of the Fajr prayer are better than the world and everything in it.","source":"Sahih Muslim, Book of Mosques 166"}}',true),

('hadith','worship','evening','{"tr":{"content":"Kim İşrak namazını kılarsa ona hac ve umrenin sevabı gibi verilir.","source":"Tirmizî, Kitabü''s-Salât 601; hasen"},"en":{"content":"Whoever prays the Duha prayer, he will have a reward like that of Hajj and Umrah.","source":"Al-Tirmidhi, Book of Prayer 601 — hasan"}}',true),

-- category: prayer
('hadith','prayer','morning','{"tr":{"content":"Dua ibadetin özüdür.","source":"Tirmizî, Kitabü''d-Deâvât 1; hasen sahih"},"en":{"content":"Supplication is the essence of worship.","source":"Al-Tirmidhi, Book of Supplications 1 — hasan sahih"}}',true),

('hadith','prayer','morning','{"tr":{"content":"Allah, duasını ısrarla sürdürenden çok hoşlanır.","source":"İbn Mâce, Kitabü''d-Duâ 1 — hasen"},"en":{"content":"Allah is pleased with His servant when he insists in his supplication to Him.","source":"Ibn Majah, Book of Supplication 1 — hasan"}}',true),

('hadith','prayer','evening','{"tr":{"content":"Gecenin son üçte birinde Allah dünya semasına iner ve şöyle seslenir: ''Bana dua eden yok mu, dua etsin de icabet edeyim? Benden bir şey isteyen yok mu, istesin de vereyim? Benden bağışlanma dileyen yok mu, bağışlanma dilesin de bağışlayayım.''","source":"Buhârî, Kitabü''t-Teheccüd 14; Müslim, Kitabü''s-Salâtü''l-Müsâfirîn 169"},"en":{"content":"Our Lord descends during the last third of each night to the lower heaven, and says: ''Is there anyone who calls on Me so that I may answer him? Is there anyone who asks Me so that I may give to him? Is there anyone who asks My forgiveness so that I may forgive him?''","source":"Sahih al-Bukhari, Book of Tahajjud 14; Sahih Muslim, Book of the Prayers of Travellers 169"}}',true),

('hadith','prayer','morning','{"tr":{"content":"En faziletli dua, ''Elhamdülillah'' demektir. En faziletli zikir ise ''Lâ ilâhe illallah'' demektir.","source":"Tirmizî, Kitabü''d-Deâvât 9; hasen"},"en":{"content":"The best supplication is ''Al-hamdu lillah'', and the best form of remembrance is ''La ilaha illallah''.","source":"Al-Tirmidhi, Book of Supplications 9 — hasan"}}',true),

-- category: dhikr
('hadith','dhikr','any','{"tr":{"content":"Rabbini zikredenle zikretmeyenin farkı, diri ile ölü arasındaki fark gibidir.","source":"Buhârî, Kitabü''d-Daavât 66"},"en":{"content":"The comparison between one who remembers his Lord and one who does not is like the comparison between the living and the dead.","source":"Sahih al-Bukhari, Book of Invocations 66"}}',true),

('hadith','dhikr','morning','{"tr":{"content":"Kim sabah ''Sübhânallâhi ve bihamdih'' diye yüz kere söylerse kıyamet günü ondan daha faziletli olan kimse gelmez, ancak aynı şeyi daha çok söyleyen kimse müstesna.","source":"Müslim, Kitabü''z-Zikr 28"},"en":{"content":"Whoever says ''Subhan Allahi wa bihamdih'' one hundred times in the morning, no one will come on the Day of Resurrection with something better than him, except one who said the same or said more.","source":"Sahih Muslim, Book of Dhikr 28"}}',true),

('hadith','dhikr','any','{"tr":{"content":"Dünyanın yükünü yiyen yoksullardan daha faziletli olan bir şeyi size söyleyeyim mi? ''Sübhânallah'', ''Elhamdülillah'', ''Lâ ilâhe illallah'' ve ''Allahu Ekber'' her namazdan sonra 33''er kez söylemek.","source":"Müslim, Kitabü''l-Mesâcid 146"},"en":{"content":"Shall I tell you something that is better for you than having a servant? Say ''Subhan Allah'', ''Alhamdulillah'' and ''Allahu Akbar'' thirty-three times each after every prayer.","source":"Sahih Muslim, Book of Mosques 146"}}',true),

('hadith','dhikr','any','{"tr":{"content":"Dilime hafif, mizanda ağır, Rahman''a sevimli iki kelime vardır: ''Sübhânallahi ve bihamdih, Sübhânallahi''l-Azîm.''","source":"Buhârî, Kitabü''d-Daavât 65; Müslim, Kitabü''z-Zikr 31"},"en":{"content":"Two words are light on the tongue, heavy in the scale, and beloved to the Most Merciful: ''Subhan Allahi wa bihamdih, Subhan Allahi''l-Azim.''","source":"Sahih al-Bukhari, Book of Invocations 65; Sahih Muslim, Book of Dhikr 31"}}',true),

('hadith','dhikr','any','{"tr":{"content":"''Lâ havle velâ kuvvete illâ billah'' cennetin hazinelerinden bir hazinedir.","source":"Buhârî, Kitabü''d-Daavât 50; Müslim, Kitabü''z-Zikr 44"},"en":{"content":"''La hawla wa la quwwata illa billah'' is a treasure from the treasures of Paradise.","source":"Sahih al-Bukhari, Book of Invocations 50; Sahih Muslim, Book of Dhikr 44"}}',true),

-- more worship hadiths
('hadith','worship','noon','{"tr":{"content":"Cuma günü, müminler için bayramdır.","source":"İbn Mâce, Kitabü''l-İkâme 98; hasen"},"en":{"content":"Friday is an Eid for the believers.","source":"Ibn Majah, Book of Establishing Prayer 98 — hasan"}}',true),

('hadith','worship','morning','{"tr":{"content":"Sizden biriniz uyuyunca şeytan ensesine üç düğüm vurur. Her düğüme ''önünde uzun gece var, uyu'' der. Kim uyanıp Allah''ı anarsa bir düğüm çözülür, abdest alırsa ikincisi çözülür, namaz kılarsa üçüncüsü de çözülür ve dinç ve güzel bir hâlde sabaha girer.","source":"Buhârî, Kitabü''t-Teheccüd 12; Müslim, Kitabü''l-Müsâfirîn 207"},"en":{"content":"When you go to sleep, Satan ties three knots at the back of your head. He breathes the following into each knot: ''The night is long so sleep on.'' When you wake up and remember Allah, one knot is undone; when you perform ablution, the second knot is undone; when you pray, the third knot is undone.","source":"Sahih al-Bukhari, Book of Tahajjud 12; Sahih Muslim, Book of Prayers of Travellers 207"}}',true),

('hadith','worship','evening','{"tr":{"content":"Akşam ile yatsı arasında namaz kılmak, Kadir Gecesini ihya etmek gibidir.","source":"Tirmizî, Kitabü''s-Salât 602; hasen"},"en":{"content":"Praying between Maghrib and Isha is like standing in prayer on the Night of Power.","source":"Al-Tirmidhi, Book of Prayer 602 — hasan"}}',true),

-- more hope hadiths
('hadith','hope','morning','{"tr":{"content":"Mümin için ne güzel! İşinin tamamı hayırdır. Bu, müminden başkası için söz konusu değildir. Sevinecek bir şeye kavuştuğunda şükreder ve bu onun için hayır olur. Bir sıkıntıya uğradığında da sabreder ve bu da onun için hayır olur.","source":"Müslim, Kitabü''z-Zühd 64"},"en":{"content":"Wondrous is the affair of the believer, for his affairs are all good. This applies to no one but the believer. If something good happens to him, he is thankful, and that is good for him. If something bad happens to him, he is patient, and that is good for him.","source":"Sahih Muslim, Book of Asceticism 64"}}',true),

('hadith','hope','any','{"tr":{"content":"Allah, ne çok çabuk vazgeçen ne de gevşek olan böyle değil, sebatla ve sürekli amel edenin amelini sever.","source":"Buhârî, Kitabü''r-Rikak 18; Müslim, Kitabü''l-Müsâfirîn 216"},"en":{"content":"Do good deeds properly, sincerely and moderately, and know that your deeds will not make you enter Paradise, and that the most beloved deed to Allah is the most regular and constant even if it were little.","source":"Sahih al-Bukhari, Book of Ar-Riqaq 18; Sahih Muslim, Book of Prayers of Travellers 216"}}',true),

('hadith','hope','evening','{"tr":{"content":"Kim yatağına abdestli yatarsa ve sonra Allah''ı anarak uyursa, uyandığında dilediği dünyalık ya da ahirete ait bir şeyi Allah''tan isterse Allah onu verir.","source":"Buhârî, Kitabü''d-Daavât 6; Müslim, Kitabü''z-Zikr 68"},"en":{"content":"Whoever goes to bed in a state of purity, and then wakes during the night and asks Allah for something of this world or the Hereafter, He will give it to him.","source":"Sahih al-Bukhari, Book of Invocations 6; Sahih Muslim, Book of Dhikr 68"}}',true),

-- more purpose hadiths
('hadith','purpose','any','{"tr":{"content":"İnsanların en hayırlısı, insanlara en çok faydalı olandır.","source":"Taberânî; İbn Ebî Şeybe; sahih li-ğayrih"},"en":{"content":"The best of people are those most beneficial to people.","source":"Al-Tabarani; Ibn Abi Shaybah — sahih li-ghayrih"}}',true),

('hadith','purpose','morning','{"tr":{"content":"Her çocuk fıtrat üzere doğar. Sonra anne-babası onu Yahudi, Hristiyan ya da Mecûsî yapar.","source":"Buhârî, Kitabü''l-Cenâiz 92; Müslim, Kitabü''l-Kader 22"},"en":{"content":"Every child is born in a state of fitrah (natural disposition). Then his parents turn him into a Jew, a Christian, or a Magian.","source":"Sahih al-Bukhari, Book of Funerals 92; Sahih Muslim, Book of Decree 22"}}',true),

('hadith','purpose','noon','{"tr":{"content":"Güzel huylar ancak bu yüzden tamamlamak için gönderildim.","source":"Buhârî, el-Edebü''l-Müfred 273; sahih"},"en":{"content":"I was sent only to perfect good moral character.","source":"Sahih al-Bukhari, Al-Adab al-Mufrad 273 — sahih"}}',true),

-- more dhikr hadiths
('hadith','dhikr','morning','{"tr":{"content":"Kim sabah ve akşam ''Sübhânallahi ve bihamdih'' diye yüz kez söylerse, denizin köpükleri kadar günah işlemiş olsa bile günahları bağışlanır.","source":"Müslim, Kitabü''z-Zikr 28"},"en":{"content":"He who recites ''Subhan Allahi wa bihamdih'' a hundred times in the morning and the evening will not be surpassed on the Day of Resurrection by anyone with better deeds than his, except someone who said the same or more.","source":"Sahih Muslim, Book of Dhikr 28"}}',true),

('hadith','dhikr','any','{"tr":{"content":"Dünyanın ve içindekilerin değeri benim yanımda şu kadar: ''Sübhânallâhi''l-Azîm ve bihamdihî.''","source":"Müslim, Kitabü''z-Zikr 31"},"en":{"content":"The world and all its contents are of less value to me than saying: ''Subhan Allahi''l-Azim wa bihamdih.''","source":"Sahih Muslim, Book of Dhikr 31"}}',true),

('hadith','dhikr','evening','{"tr":{"content":"Kim akşamleyin üç kez ''E''ûzü billâhi''s-semî''i''l-alîmi mine''ş-şeytâni''r-racîm'' deyip Haşr Suresi''nin son üç ayetini okursa, Allah onun için yetmiş bin melek gönderir.","source":"Tirmizî, Kitabü''d-Deâvât 22; hasen"},"en":{"content":"Whoever says in the evening three times: ''I seek refuge in Allah, the Hearing and Knowing, from the accursed devil,'' and then recites the last three verses of Surah Al-Hashr, Allah will appoint seventy thousand angels for him.","source":"Al-Tirmidhi, Book of Supplications 22 — hasan"}}',true),

('hadith','dhikr','any','{"tr":{"content":"Kişi Allah''ın zikrini bırakmayacak, yoksa münafık damgasını yer.","source":"Müslim, Kitabü''l-Münâfikîn 1"},"en":{"content":"Do not abandon the remembrance of Allah, lest your heart becomes hard.","source":"Sahih Muslim, Book of the Munafiqun 1"}}',true),

-- more prayer hadiths
('hadith','prayer','any','{"tr":{"content":"Sıkıntıya düştüğünüzde önce Allah''a dua edin.","source":"Buhârî, Kitabü''d-Daavât 1; Müslim, Kitabü''z-Zikr 1"},"en":{"content":"When you ask, ask of Allah; when you seek help, seek help from Allah.","source":"Sahih al-Bukhari, Book of Invocations 1; Sahih Muslim, Book of Dhikr 1"}}',true),

('hadith','prayer','evening','{"tr":{"content":"Kim gece Âyetü''l-Kürsi''yi okursa sabah olana kadar Allah tarafından bir muhafız ona vekilleştirilir.","source":"Buhârî, Kitabü''l-Vekâle 10"},"en":{"content":"Whoever recites Ayat al-Kursi before sleeping will have a guardian from Allah who will protect him, and Satan will not be able to come near him until morning.","source":"Sahih al-Bukhari, Book of Agency 10"}}',true),

('hadith','prayer','morning','{"tr":{"content":"Sabah uyanınca şöyle söyle: ''Allahümme beke asbehnâ ve bike emseynâ...'' Akşam olunca da: ''Allahümme bike emseynâ ve bike asbehnâ...''","source":"Ebû Dâvûd, Kitabü''l-Edeb 18; hasen"},"en":{"content":"In the morning say: ''O Allah, by You we enter the morning and by You we enter the evening...'' and in the evening say the same with morning and evening switched.","source":"Abu Dawud, Book of Manners 18 — hasan"}}',true);

-- ============================================================
-- PRAYERS / DUAS (Quran-sourced + authentic Sunnah duas)
-- ============================================================

insert into public.content_items (type, category, recommended_time, translations, is_active) values

-- Morning Adhkar
('prayer','prayer','morning','{"tr":{"content":"Sabah uyanıldığında okunur. ''Allah''ım! Senin sayende sabaha erdik, Senin sayende akşama erdik, Senin sayende yaşarız ve Senin sayende ölürüz. Dönüş de Sanadır.''","arabicText":"اللَّهُمَّ بِكَ أَصْبَحْنَا وَبِكَ أَمْسَيْنَا وَبِكَ نَحْيَا وَبِكَ نَمُوتُ وَإِلَيْكَ النُّشُورُ","transliteration":"Allâhümme bike asbah''nâ ve bike emseynâ ve bike nah''yâ ve bike nemûtü ve ileyke''n-nüşûr","source":"Ebû Dâvûd, Edeb 18"},"en":{"content":"Recited upon waking. ''O Allah, by You we enter the morning, by You we enter the evening, by You we live and by You we die, and to You is the resurrection.''","arabicText":"اللَّهُمَّ بِكَ أَصْبَحْنَا وَبِكَ أَمْسَيْنَا وَبِكَ نَحْيَا وَبِكَ نَمُوتُ وَإِلَيْكَ النُّشُورُ","transliteration":"Allahumma bika asbahna wa bika amsayna wa bika nahya wa bika namutu wa ilayka''n-nushur","source":"Abu Dawud, Adab 18"}}',true),

('prayer','prayer','morning','{"tr":{"content":"Sabah namazından sonra üç kez okunur. ''Allah''ım! Sen selamsın, selam Senden gelir; ey celal ve ikram sahibi, sen yücesin.''","arabicText":"اللَّهُمَّ أَنْتَ السَّلَامُ وَمِنْكَ السَّلَامُ تَبَارَكْتَ يَا ذَا الْجَلَالِ وَالْإِكْرَامِ","transliteration":"Allâhümme ente''s-selâmü ve minke''s-selâmü tebârekte yâ ze''l-celâli ve''l-ikrâm","source":"Müslim, Mesâcid 135"},"en":{"content":"Recited three times after Fajr. ''O Allah, You are Peace and from You comes peace; blessed are You, O Possessor of Majesty and Honor.''","arabicText":"اللَّهُمَّ أَنْتَ السَّلَامُ وَمِنْكَ السَّلَامُ تَبَارَكْتَ يَا ذَا الْجَلَالِ وَالْإِكْرَامِ","transliteration":"Allahumma anta''s-salamu wa minka''s-salamu tabarakta ya dha''l-jalali wa''l-ikram","source":"Sahih Muslim, Mosques 135"}}',true),

('prayer','prayer','morning','{"tr":{"content":"''Allah''ım! Senden Senin hakkındaki bilginle ilim, senden gücün yettiği şeyi yapabilme ve Senin büyük fazlından istemek istiyorum.''","arabicText":"اللَّهُمَّ إِنِّي أَسْأَلُكَ بِعِلْمِكَ الْغَيْبَ وَقُدْرَتِكَ عَلَى الْخَلْقِ أَحْيِنِي مَا عَلِمْتَ الْحَيَاةَ خَيْرًا لِي وَتَوَفَّنِي إِذَا عَلِمْتَ الْوَفَاةَ خَيْرًا لِي","transliteration":"Allâhümme innî es''elüke bi''ilmike''l-ğaybe ve kudretike ale''l-halk...","source":"Nesâî, Sehv 62; sahih"},"en":{"content":"''O Allah, I ask You by Your knowledge of the unseen and Your power over creation: keep me alive as long as life is good for me, and cause me to die when death is better for me.''","arabicText":"اللَّهُمَّ إِنِّي أَسْأَلُكَ بِعِلْمِكَ الْغَيْبَ وَقُدْرَتِكَ عَلَى الْخَلْقِ أَحْيِنِي مَا عَلِمْتَ الْحَيَاةَ خَيْرًا لِي وَتَوَفَّنِي إِذَا عَلِمْتَ الْوَفَاةَ خَيْرًا لِي","transliteration":"Allahumma inni as''aluka bi''ilmika''l-ghayba wa qudratika ''ala''l-khalq...","source":"Al-Nasa''i, As-Sahw 62 — sahih"}}',true),

('prayer','prayer','morning','{"tr":{"content":"Sabah üç kez okunur. ''Göklerin ve yerin Rabbi olan Allah''ın adıyla; O''nun adıyla birlikte hiçbir şey zarar veremez ne yerde ne de gökte. O her şeyi işiten ve bilendir.''","arabicText":"بِسْمِ اللَّهِ الَّذِي لَا يَضُرُّ مَعَ اسْمِهِ شَيْءٌ فِي الْأَرْضِ وَلَا فِي السَّمَاءِ وَهُوَ السَّمِيعُ الْعَلِيمُ","transliteration":"Bismillâhi''llezî lâ yadurru me''a''smihî şey''ün fi''l-ardi ve lâ fi''s-semâi ve hüve''s-semî''u''l-alîm","source":"Ebû Dâvûd, Edeb 18; Tirmizî, Daavât 13 — sahih"},"en":{"content":"Recited three times in the morning. ''In the name of Allah with whose name nothing can harm in the earth or the heavens, and He is the All-Hearing, All-Knowing.''","arabicText":"بِسْمِ اللَّهِ الَّذِي لَا يَضُرُّ مَعَ اسْمِهِ شَيْءٌ فِي الْأَرْضِ وَلَا فِي السَّمَاءِ وَهُوَ السَّمِيعُ الْعَلِيمُ","transliteration":"Bismillahi''lladhi la yadurru ma''a''smihi shay''un fi''l-ardi wa la fi''s-sama''i wa huwa''s-sami''u''l-alim","source":"Abu Dawud, Adab 18; Tirmidhi, Du''a 13 — sahih"}}',true),

-- Evening Adhkar
('prayer','prayer','evening','{"tr":{"content":"Akşam okunur. ''Allah''ım! Senin sayende akşama erdik, Senin sayende sabaha erdik, Senin sayende yaşarız ve Senin sayende ölürüz. Dönüş de Sanadır.''","arabicText":"اللَّهُمَّ بِكَ أَمْسَيْنَا وَبِكَ أَصْبَحْنَا وَبِكَ نَحْيَا وَبِكَ نَمُوتُ وَإِلَيْكَ الْمَصِيرُ","transliteration":"Allâhümme bike emseynâ ve bike asbah''nâ ve bike nah''yâ ve bike nemûtü ve ileyke''l-masîr","source":"Ebû Dâvûd, Edeb 18"},"en":{"content":"Recited in the evening. ''O Allah, by You we enter the evening, by You we enter the morning, by You we live and by You we die, and to You is the final destination.''","arabicText":"اللَّهُمَّ بِكَ أَمْسَيْنَا وَبِكَ أَصْبَحْنَا وَبِكَ نَحْيَا وَبِكَ نَمُوتُ وَإِلَيْكَ الْمَصِيرُ","transliteration":"Allahumma bika amsayna wa bika asbahna wa bika nahya wa bika namutu wa ilayka''l-masir","source":"Abu Dawud, Adab 18"}}',true),

('prayer','prayer','evening','{"tr":{"content":"Seyyidü''l-İstiğfar — Efendimiz (s.a.v.)''in istğifar duaları arasında en üstün kabul ettikleri. ''Allah''ım! Sen benim Rabbimsin. Senden başka ilah yoktur. Beni Sen yarattın. Ben Senin kulunum. Gücüm yettiğince Sana olan ahit ve vaadim üzereyim. Yaptıklarımın şerrinden Sana sığınırım. Üzerimdeki nimetini ikrar ediyorum. Günahımı da itiraf ediyorum. Beni bağışla! Çünkü günahları Sen''den başkası affetmez.''","arabicText":"اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلَّا أَنْتَ خَلَقْتَنِي وَأَنَا عَبْدُكَ وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ وَأَبُوءُ بِذَنْبِي فَاغْفِرْ لِي فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ","transliteration":"Allâhümme ente Rabbî, lâ ilâhe illâ ente, halaktenî ve ene abdüke, ve ene alâ ahdike ve va''dike mâ''steta''tü, e''ûzü bike min şerri mâ sana''tü, ebû''ü leke bini''metike aleyye ve ebû''ü bizenbî feğfirlî fe innehü lâ yağfiru''z-zünûbe illâ ente","source":"Buhârî, Daavât 2"},"en":{"content":"Sayyid al-Istighfar — the Master Supplication for Forgiveness. ''O Allah! You are my Lord. None has the right to be worshipped except You. You created me and I am Your slave. I am faithful to my covenant and my promise to You as much as I can. I seek refuge with You from the evil of what I have done. I acknowledge before You all the blessings You have bestowed upon me, and I confess to You my sins. So forgive me, for none forgives sins but You.''","arabicText":"اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلَّا أَنْتَ خَلَقْتَنِي وَأَنَا عَبْدُكَ وَأَنَا عَلَى عَهْدِكَ وَوَعْدِكَ مَا اسْتَطَعْتُ أَعُوذُ بِكَ مِنْ شَرِّ مَا صَنَعْتُ أَبُوءُ لَكَ بِنِعْمَتِكَ عَلَيَّ وَأَبُوءُ بِذَنْبِي فَاغْفِرْ لِي فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ","transliteration":"Allahumma anta Rabbi la ilaha illa anta khalaqtani wa ana abduka wa ana ala ahdika wa wa''dika ma''stata''tu a''udhu bika min sharri ma sana''tu abu''u laka bini''matika ''alayya wa abu''u bidhanbî faghfir li fa innahu la yaghfiru''dh-dhunuba illa anta","source":"Sahih al-Bukhari, Invocations 2"}}',true),

('prayer','prayer','evening','{"tr":{"content":"''Eûzü bikâlimatillâhi''t-tâmmâti min şerri mâ halak'' — üç kez. ''Allah''ın yarattıklarının şerrinden Allah''ın eksiksiz kelimelerine sığınırım.''","arabicText":"أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ","transliteration":"E''ûzü bikâlimatillâhi''t-tâmmâti min şerri mâ halak","source":"Müslim, Zikr 54"},"en":{"content":"''I seek refuge in the perfect words of Allah from the evil of what He has created'' — three times in the evening.","arabicText":"أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ","transliteration":"A''udhu bikalimati''llahi''t-tammati min sharri ma khalaq","source":"Sahih Muslim, Dhikr 54"}}',true),

-- Quran-sourced duas
('prayer','prayer','any','{"tr":{"content":"Hz. Musa''nın duası: ''Rabbim! Göğsümü genişlet. İşimi bana kolaylaştır. Dilimden tutukluğu çöz ki sözümü anlasınlar.''","arabicText":"رَبِّ اشْرَحْ لِي صَدْرِي وَيَسِّرْ لِي أَمْرِي وَاحْلُلْ عُقْدَةً مِنْ لِسَانِي يَفْقَهُوا قَوْلِي","transliteration":"Rabbi''şrah lî sadrî ve yessir lî emrî va''hlül ukdeten min lisânî yefkahû kavlî","source":"Tâhâ Suresi, 25-28. Ayetler"},"en":{"content":"The prayer of Prophet Musa: ''My Lord, expand for me my breast and ease for me my task and untie the knot from my tongue that they may understand my speech.''","arabicText":"رَبِّ اشْرَحْ لِي صَدْرِي وَيَسِّرْ لِي أَمْرِي وَاحْلُلْ عُقْدَةً مِنْ لِسَانِي يَفْقَهُوا قَوْلِي","transliteration":"Rabbi''shrah li sadri wa yassir li amri wa''hlul ''uqdatan min lisani yafqahu qawli","source":"Surah Ta-Ha, 20:25-28"}}',true),

('prayer','prayer','any','{"tr":{"content":"''Rabbimiz! Bize dünyada iyilik ver ve ahirette de iyilik ver ve bizi cehennem azabından koru.''","arabicText":"رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ","transliteration":"Rabbenâ âtinâ fi''d-dünyâ haseneten ve fi''l-âhirati haseneten ve kinâ azâbe''n-nâr","source":"Bakara Suresi, 201. Ayet"},"en":{"content":"''Our Lord, give us good in this world and good in the Hereafter and protect us from the punishment of the Fire.''","arabicText":"رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ","transliteration":"Rabbana atina fi''d-dunya hasanatan wa fi''l-akhirati hasanatan wa qina ''adhaba''n-nar","source":"Surah Al-Baqarah, 2:201"}}',true),

('prayer','prayer','any','{"tr":{"content":"Hz. Yûsuf''un duası: ''Rabbim! Gerçekten mülkten bir nasip verdin ve bana rüyaların tabirini öğrettin. Ey gökleri ve yeri yaratan! Dünyada da ahirette de benim velim Sensin. Müslüman olarak canımı al ve beni salihlere kat.''","arabicText":"رَبِّ قَدْ آتَيْتَنِي مِنَ الْمُلْكِ وَعَلَّمْتَنِي مِنْ تَأْوِيلِ الْأَحَادِيثِ فَاطِرَ السَّمَاوَاتِ وَالْأَرْضِ أَنْتَ وَلِيِّي فِي الدُّنْيَا وَالْآخِرَةِ تَوَفَّنِي مُسْلِمًا وَأَلْحِقْنِي بِالصَّالِحِينَ","transliteration":"Rabbi kad âteyteni mine''l-mülki ve allemteni min te''vîli''l-ehâdîs, fâtıra''s-semâvâti ve''l-ard, ente veliyyî fi''d-dünyâ ve''l-âhireti teveffenî müslimen ve elhıknî bi''s-sâlihîn","source":"Yûsuf Suresi, 101. Ayet"},"en":{"content":"The prayer of Prophet Yusuf: ''My Lord, You have given me something of sovereignty and taught me of the interpretation of dreams. Creator of the heavens and earth, You are my protector in this world and in the Hereafter. Cause me to die a Muslim and join me with the righteous.''","arabicText":"رَبِّ قَدْ آتَيْتَنِي مِنَ الْمُلْكِ وَعَلَّمْتَنِي مِنْ تَأْوِيلِ الْأَحَادِيثِ فَاطِرَ السَّمَاوَاتِ وَالْأَرْضِ أَنْتَ وَلِيِّي فِي الدُّنْيَا وَالْآخِرَةِ تَوَفَّنِي مُسْلِمًا وَأَلْحِقْنِي بِالصَّالِحِينَ","transliteration":"Rabbi qad ataytani mina''l-mulki wa allamtani min ta''wili''l-ahadith fatira''s-samawati wa''l-ard anta waliyyî fi''d-dunya wa''l-akhirati tawaffani musliman wa alhiqni bi''s-salihin","source":"Surah Yusuf, 12:101"}}',true),

('prayer','prayer','any','{"tr":{"content":"Hz. Eyyûb''un duası: ''Gerçekten bana dert dokundu, Sen ise merhametlilerin en merhametlisisin.''","arabicText":"أَنِّي مَسَّنِيَ الضُّرُّ وَأَنْتَ أَرْحَمُ الرَّاحِمِينَ","transliteration":"Ennî messeniye''d-durru ve ente erhamü''r-râhimîn","source":"Enbiyâ Suresi, 83. Ayet"},"en":{"content":"The prayer of Prophet Ayyub: ''Indeed, adversity has touched me, and You are the Most Merciful of the merciful.''","arabicText":"أَنِّي مَسَّنِيَ الضُّرُّ وَأَنْتَ أَرْحَمُ الرَّاحِمِينَ","transliteration":"Anni massaniya''d-durru wa anta arhamu''r-rahimin","source":"Surah Al-Anbiya, 21:83"}}',true),

('prayer','prayer','any','{"tr":{"content":"Hz. Yûnus''un duası: ''Senden başka ilah yoktur. Seni tenzih ederim. Gerçekten ben zalimlerden oldum.''","arabicText":"لَا إِلَهَ إِلَّا أَنْتَ سُبْحَانَكَ إِنِّي كُنْتُ مِنَ الظَّالِمِينَ","transliteration":"Lâ ilâhe illâ ente sübhâneke innî küntü mine''z-zâlimîn","source":"Enbiyâ Suresi, 87. Ayet"},"en":{"content":"The prayer of Prophet Yunus: ''There is no deity except You; exalted are You. Indeed, I have been of the wrongdoers.''","arabicText":"لَا إِلَهَ إِلَّا أَنْتَ سُبْحَانَكَ إِنِّي كُنْتُ مِنَ الظَّالِمِينَ","transliteration":"La ilaha illa anta subhanaka inni kuntu mina''z-zalimin","source":"Surah Al-Anbiya, 21:87"}}',true),

('prayer','prayer','any','{"tr":{"content":"Hz. İbrâhim''in duası: ''Rabbim! Beni namazı hakkıyla kılanlardan eyle ve soyumdan da öyle kimseler yetiştir. Rabbimiz! Duamı kabul et.''","arabicText":"رَبِّ اجْعَلْنِي مُقِيمَ الصَّلَاةِ وَمِنْ ذُرِّيَّتِي رَبَّنَا وَتَقَبَّلْ دُعَاءِ","transliteration":"Rabbi''c''alnî mukîme''s-salâti ve min zürriyyetî rabbenâ ve tekabbel dü''â''","source":"İbrâhim Suresi, 40. Ayet"},"en":{"content":"The prayer of Prophet Ibrahim: ''My Lord, make me an establisher of prayer, and from my descendants. Our Lord, and accept my supplication.''","arabicText":"رَبِّ اجْعَلْنِي مُقِيمَ الصَّلَاةِ وَمِنْ ذُرِّيَّتِي رَبَّنَا وَتَقَبَّلْ دُعَاءِ","transliteration":"Rabbij''alni muqima''s-salati wa min dhurriyyati Rabbana wa taqabbal du''a''","source":"Surah Ibrahim, 14:40"}}',true),

('prayer','prayer','morning','{"tr":{"content":"''Allah''ım! Senden bu günün hayrını, fethini, yardımını, nurunu ve bereketini istiyorum; bu günün şerrinden de Sana sığınıyorum.''","arabicText":"اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَ هَذَا الْيَوْمِ فَتْحَهُ وَنَصْرَهُ وَنُورَهُ وَبَرَكَتَهُ وَهُدَاهُ وَأَعُوذُ بِكَ مِنْ شَرِّ مَا فِيهِ وَشَرِّ مَا بَعْدَهُ","transliteration":"Allâhümme innî es''elüke hayra hâze''l-yevmi fethahü ve nasrahü ve nûrahü ve bereketehü ve hüdâhü ve e''ûzü bike min şerri mâ fîhi ve şerri mâ ba''dehü","source":"Ebû Dâvûd, Edeb 18; sahih"},"en":{"content":"''O Allah, I ask You for the good of this day, its victories, its help, its light, its blessings and its guidance, and I take refuge in You from the evil within it and the evil of what comes after it.''","arabicText":"اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَ هَذَا الْيَوْمِ فَتْحَهُ وَنَصْرَهُ وَنُورَهُ وَبَرَكَتَهُ وَهُدَاهُ وَأَعُوذُ بِكَ مِنْ شَرِّ مَا فِيهِ وَشَرِّ مَا بَعْدَهُ","transliteration":"Allahumma inni as''aluka khayra hadha''l-yawmi fathahu wa nasrahu wa nurahu wa barakatahu wa hudahu wa a''udhu bika min sharri ma fihi wa sharri ma ba''dahu","source":"Abu Dawud, Adab 18 — sahih"}}',true),

('prayer','prayer','evening','{"tr":{"content":"Yatarken okunacak dua. ''Allah''ım! Senin adınla yaşar ve ölürüm.''","arabicText":"اللَّهُمَّ بِاسْمِكَ أَمُوتُ وَأَحْيَا","transliteration":"Allâhümme bi''smike emûtü ve ah''yâ","source":"Buhârî, Daavât 9"},"en":{"content":"Supplication before sleeping. ''O Allah, with Your name I die and I live.''","arabicText":"اللَّهُمَّ بِاسْمِكَ أَمُوتُ وَأَحْيَا","transliteration":"Allahumma bismika amutu wa ahya","source":"Sahih al-Bukhari, Invocations 9"}}',true),

('prayer','prayer','evening','{"tr":{"content":"Uyumadan önce İhlâs, Felak ve Nâs surelerini üç kez okuyup elleri üfleyerek vücudu sıvazla. Hz. Peygamber böyle yapardı.","arabicText":"قُلْ هُوَ اللَّهُ أَحَدٌ... قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ... قُلْ أَعُوذُ بِرَبِّ النَّاسِ","transliteration":"Kul huvallâhu ahad... Kul e''ûzü bi rabbi''l-felak... Kul e''ûzü bi rabbi''n-nâs","source":"Buhârî, Fedâilü''l-Kur''ân 14; Ebû Dâvûd, Edeb 23"},"en":{"content":"Before sleeping, recite Al-Ikhlas, Al-Falaq and An-Nas three times and wipe over the body after blowing into the hands. The Prophet used to do this.","arabicText":"قُلْ هُوَ اللَّهُ أَحَدٌ... قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ... قُلْ أَعُوذُ بِرَبِّ النَّاسِ","transliteration":"Qul huwa''llahu ahad... Qul a''udhu bi rabbi''l-falaq... Qul a''udhu bi rabbi''n-nas","source":"Sahih al-Bukhari, Virtues of the Quran 14; Abu Dawud, Adab 23"}}',true),

('prayer','prayer','any','{"tr":{"content":"Âyetü''l-Kürsî. ''Allah... Kendisinden başka hiçbir ilah olmayan, diri ve kayyum olandır. Onu ne bir uyuklama ne de uyku yakalar. Göklerdeki her şey ve yerdeki her şey O''nundur. O''nun izni olmaksızın katında kim şefaat edebilir? O, önlerindekini de arkalarındakini de bilir. Onlar O''nun ilminden, dilediği kadarından başka hiçbir şeyi kavrayamazlar. O''nun kürsüsü gökleri ve yeri kaplar. Onların korunması O''na ağır gelmez. O, çok yüce ve çok büyüktür.''","arabicText":"اللَّهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلَّا بِإِذْنِهِ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ بِشَيْءٍ مِنْ عِلْمِهِ إِلَّا بِمَا شَاءَ وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ وَلَا يَئُودُهُ حِفْظُهُمَا وَهُوَ الْعَلِيُّ الْعَظِيمُ","transliteration":"Allâhu lâ ilâhe illâ hüve''l-hayyü''l-kayyûm, lâ te''huzühü sinetün ve lâ nevm, lehü mâ fi''s-semâvâti ve mâ fi''l-ard, men zellezî yeşfe''u indehü illâ bi''iznihî, ya''lemü mâ beyne eydîhim ve mâ halfehüm, ve lâ yühîtûne bişey''in min ilmihî illâ bimâ şâe, vesi''a kürsiyyühü''s-semâvâti ve''l-ard, ve lâ ye''ûdühü hıfzuhümâ ve hüve''l-aliyyü''l-azîm","source":"Bakara Suresi, 255. Ayet"},"en":{"content":"Ayat al-Kursi. ''Allah — there is no deity except Him, the Ever-Living, the Sustainer of existence. Neither drowsiness overtakes Him nor sleep. To Him belongs whatever is in the heavens and whatever is on the earth. Who is it that can intercede with Him except by His permission? He knows what is before them and what will be after them, and they encompass not a thing of His knowledge except for what He wills. His Throne extends over the heavens and the earth, and their preservation tires Him not. And He is the Most High, the Most Great.''","arabicText":"اللَّهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلَّا بِإِذْنِهِ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ بِشَيْءٍ مِنْ عِلْمِهِ إِلَّا بِمَا شَاءَ وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ وَلَا يَئُودُهُ حِفْظُهُمَا وَهُوَ الْعَلِيُّ الْعَظِيمُ","transliteration":"Allahu la ilaha illa huwa''l-hayyu''l-qayyum la ta''khudhhu sinatun wa la nawm lahu ma fi''s-samawati wa ma fi''l-ard man dhallladhi yashfa''u ''indahu illa bi''idhnihi ya''lamu ma bayna aydihim wa ma khalfahum wa la yuhituna bishay''in min ''ilmihi illa bima sha''a wasi''a kursiyyuhu''s-samawati wa''l-arda wa la ya''uduhu hifzuhuma wa huwa''l-aliyyu''l-azim","source":"Surah Al-Baqarah, 2:255"}}',true),

('prayer','prayer','morning','{"tr":{"content":"''Allah''ım! Senden ilim, güzel amel ve helal rızık istiyorum.''","arabicText":"اللَّهُمَّ إِنِّي أَسْأَلُكَ عِلْمًا نَافِعًا وَرِزْقًا طَيِّبًا وَعَمَلًا مُتَقَبَّلًا","transliteration":"Allâhümme innî es''elüke ilmen nâfia''n ve rızkan tayyiben ve amelen mütekabbelen","source":"İbn Mâce, İkâme 25; sahih"},"en":{"content":"''O Allah, I ask You for beneficial knowledge, good provision and accepted deeds.''","arabicText":"اللَّهُمَّ إِنِّي أَسْأَلُكَ عِلْمًا نَافِعًا وَرِزْقًا طَيِّبًا وَعَمَلًا مُتَقَبَّلًا","transliteration":"Allahumma inni as''aluka ''ilman nafi''an wa rizqan tayyiban wa ''amalan mutaqabbalan","source":"Ibn Majah, Iqamah 25 — sahih"}}',true),

('prayer','prayer','any','{"tr":{"content":"Sıkıntı ve üzüntü anında Hz. Peygamber''in duası: ''Allah''ım! Ben Senin kulunum, kulunun oğluyum, cariyenin oğluyum. Alnım Senin elindedir, hakkımda hükmün geçerlidir, bana takdirin adildir.''","arabicText":"اللَّهُمَّ إِنِّي عَبْدُكَ وَابْنُ عَبْدِكَ وَابْنُ أَمَتِكَ نَاصِيَتِي بِيَدِكَ مَاضٍ فِيَّ حُكْمُكَ عَدْلٌ فِيَّ قَضَاؤُكَ","transliteration":"Allâhümme innî abdüke vebnu abdike vebnu emetike, nâsıyetî biyedike, mâdin fiyye hükmüke, adlün fiyye kadâ''üke","source":"Ahmed b. Hanbel, Müsned 3528; sahih"},"en":{"content":"The Prophet''s supplication in times of distress and sorrow: ''O Allah, I am Your servant, the son of Your servant, the son of Your maidservant. My forelock is in Your hand. Your decree over me is just. Your judgment concerning me is fair.''","arabicText":"اللَّهُمَّ إِنِّي عَبْدُكَ وَابْنُ عَبْدِكَ وَابْنُ أَمَتِكَ نَاصِيَتِي بِيَدِكَ مَاضٍ فِيَّ حُكْمُكَ عَدْلٌ فِيَّ قَضَاؤُكَ","transliteration":"Allahumma inni abduka wabnu abdika wabnu amatika nasiyati biyadika madin fiyya hukmuka adlun fiyya qada''uka","source":"Ahmad ibn Hanbal, Musnad 3528 — sahih"}}',true),

('prayer','prayer','any','{"tr":{"content":"İstihare duası: ''Allah''ım! Senin ilminle hayırlısını seçmeni, Senin kudretinle güç vermeni ve Senin büyük fazlından istemeni istiyorum. Sen güç yetirir ben yetiremem. Sen bilirsin ben bilemem. Sen gaipler hakkında çok bilensin.''","arabicText":"اللَّهُمَّ إِنِّي أَسْتَخِيرُكَ بِعِلْمِكَ وَأَسْتَقْدِرُكَ بِقُدْرَتِكَ وَأَسْأَلُكَ مِنْ فَضْلِكَ الْعَظِيمِ فَإِنَّكَ تَقْدِرُ وَلَا أَقْدِرُ وَتَعْلَمُ وَلَا أَعْلَمُ وَأَنْتَ عَلَّامُ الْغُيُوبِ","transliteration":"Allâhümme innî estahîrüke bi''ilmike ve estakdirüke bikudretike ve es''elüke min fadlike''l-azîm, feinneke takdiru ve lâ akdiru ve ta''lemü ve lâ a''lemü ve ente allâmü''l-ğuyûb","source":"Buhârî, Cuma 25"},"en":{"content":"The Istikhara supplication: ''O Allah, I seek Your guidance by Your knowledge, and I seek Your help by Your power, and I ask You from Your immense favour. For You have power and I have none, You know and I do not know, and You are the Knower of the unseen.''","arabicText":"اللَّهُمَّ إِنِّي أَسْتَخِيرُكَ بِعِلْمِكَ وَأَسْتَقْدِرُكَ بِقُدْرَتِكَ وَأَسْأَلُكَ مِنْ فَضْلِكَ الْعَظِيمِ فَإِنَّكَ تَقْدِرُ وَلَا أَقْدِرُ وَتَعْلَمُ وَلَا أَعْلَمُ وَأَنْتَ عَلَّامُ الْغُيُوبِ","transliteration":"Allahumma inni astakhiruka bi''ilmika wa astaqdiruka biqudratika wa as''aluka min fadlika''l-azim fa innaka taqdiru wa la aqdiru wa ta''lamu wa la a''lamu wa anta ''allamu''l-ghuyub","source":"Sahih al-Bukhari, Friday Prayer 25"}}',true),

('prayer','prayer','morning','{"tr":{"content":"''Allah''ım! Bu sabah ve bu güne kavuşmam sayesinde bana ve tüm yaratılışa sahip olan Senin. Allah''ım! Bu sabah benden bir nimet geldiyse ya da herhangi bir yaratılışından birinden olduysa, yalnızca Senden ve Sen teksinden. Sana hamd ederim ve Sana şükrederim.''","arabicText":"اللَّهُمَّ مَا أَصْبَحَ بِي مِنْ نِعْمَةٍ أَوْ بِأَحَدٍ مِنْ خَلْقِكَ فَمِنْكَ وَحْدَكَ لَا شَرِيكَ لَكَ فَلَكَ الْحَمْدُ وَلَكَ الشُّكْرُ","transliteration":"Allâhümme mâ asbaha bî min ni''metin ev bi''ahadin min halkıke feminkevelâ şerîke leke feleke''l-hamdu ve lekü''ş-şükür","source":"Ebû Dâvûd, Edeb 18; hasen"},"en":{"content":"''O Allah, whatever blessing I or any of Your creation have received this morning, it is from You alone, You have no partner. To You belongs all praise and thanks.''","arabicText":"اللَّهُمَّ مَا أَصْبَحَ بِي مِنْ نِعْمَةٍ أَوْ بِأَحَدٍ مِنْ خَلْقِكَ فَمِنْكَ وَحْدَكَ لَا شَرِيكَ لَكَ فَلَكَ الْحَمْدُ وَلَكَ الشُّكْرُ","transliteration":"Allahumma ma asbaha bi min ni''matin aw bi''ahadin min khalqika faminka wahdaka la sharika laka falaka''l-hamdu wa laka''sh-shukr","source":"Abu Dawud, Adab 18 — hasan"}}',true);

-- ============================================================
-- WORSHIP (type='worship') — virtues and guidance on acts of worship
-- ============================================================

insert into public.content_items (type, category, recommended_time, translations, is_active) values

('worship','worship','morning','{"tr":{"content":"Sabah namazını cemaatle kılan, gün boyu Allah''ın himayesindedir. Hz. Peygamber şöyle buyurdu: ''Kim sabah namazını kılarsa Allah''ın zimmeti altındadır.'' Güne bu koruma altında başlamak büyük bir lütuftur.","source":"Müslim, Mesâcid 257"},"en":{"content":"Whoever prays Fajr in congregation is under Allah''s protection for the day. The Prophet said: ''Whoever prays the morning prayer is under the protection of Allah.'' Starting the day under this protection is a great blessing.","source":"Sahih Muslim, Mosques 257"}}',true),

('worship','worship','morning','{"tr":{"content":"Sabah namazından sonra güneş doğana kadar Allah''ı zikreden ve ardından iki rekat namaz kılan kişi, tam bir hac ve umrenin sevabını kazanır. Hz. Peygamber bu ameli tavsiye etmiştir.","source":"Tirmizî, Cuma 59; hasen"},"en":{"content":"Whoever remains in his place after Fajr remembering Allah until sunrise and then prays two rak''ahs, he will have a reward like that of a complete Hajj and Umrah. The Prophet recommended this practice.","source":"Al-Tirmidhi, Friday 59 — hasan"}}',true),

('worship','worship','noon','{"tr":{"content":"Öğle namazından önce dört rekat kılmanın fazileti büyüktür. Hz. Peygamber şöyle buyurdu: ''Kim öğle namazından önce dört rekat kılarsa, gökyüzünde oruç tutanların adedi kadar melekler o kişi için istiğfar eder.''","source":"Ebû Dâvûd, Salât 22; hasen"},"en":{"content":"The virtue of praying four rak''ahs before Dhuhr is great. The Prophet said: ''Whoever prays four rak''ahs before Dhuhr prayer, the angels numbering the fasting ones in the sky will seek forgiveness for him.''","source":"Abu Dawud, Prayer 22 — hasan"}}',true),

('worship','worship','any','{"tr":{"content":"Oruç bir kalkandır; günahlardan, cehennem ateşinden ve kötülüklerden koruyan bir siper gibidir. Ramazanda tutulan orucun yanı sıra Pazartesi-Perşembe ve ayın 13-14-15. günlerinde tutulan oruç da çok faziletlidir.","source":"Buhârî, Savm 2; Müslim, Sıyam 167"},"en":{"content":"Fasting is a shield — a protective barrier against sins, hellfire and evil. In addition to Ramadan fasting, fasting on Mondays and Thursdays and the 13th, 14th and 15th of each lunar month is highly virtuous.","source":"Sahih al-Bukhari, Fasting 2; Sahih Muslim, Fasting 167"}}',true),

('worship','worship','any','{"tr":{"content":"Zekat, sadece verilen malı azaltmaz; aksine Allah onu bereketlendirir ve kişinin mülkünü artırır. Hz. Peygamber şöyle buyurdu: ''Sadaka malı azaltmaz.'' Bu ilahi bir sözdür.","source":"Müslim, Birr 69"},"en":{"content":"Zakat does not merely reduce one''s wealth; rather Allah blesses it and increases one''s possessions. The Prophet said: ''Charity does not decrease wealth.'' This is a divine promise.","source":"Sahih Muslim, Virtue 69"}}',true),

('worship','worship','noon','{"tr":{"content":"Cuma namazı, Müslümanların haftada bir kez bir araya gelerek toplumsal birliği pekiştirdiği mübarek bir ibadettir. Hz. Peygamber Cuma gününü ''haftanın bayramı'' olarak nitelendirmiştir. Cuma günü salâvat getirmenin özel fazileti vardır.","source":"İbn Mâce, İkâme 98"},"en":{"content":"Friday prayer is a blessed act of worship where Muslims gather weekly to strengthen communal unity. The Prophet described Friday as ''the Eid of the week.'' Sending salawat upon the Prophet on Friday has special virtue.","source":"Ibn Majah, Iqamah 98"}}',true),

('worship','worship','any','{"tr":{"content":"Kur''ân-ı Kerîm okumak hem kalbi hem ruhu besler. Hz. Peygamber şöyle buyurmuştur: ''İçinde Kur''ân bulunmayan kalp, ıssız bir ev gibidir.'' Her gün birkaç ayet okumak, kalbi Allah''a bağlı tutar.","source":"Tirmizî, Kıraât 2; hasen"},"en":{"content":"Reciting the Quran nourishes both the heart and the soul. The Prophet said: ''A heart that contains no Quran is like a ruined house.'' Reading even a few verses each day keeps the heart connected to Allah.","source":"Al-Tirmidhi, Recitation 2 — hasan"}}',true),

('worship','worship','morning','{"tr":{"content":"Abdest, yalnızca namaz için bir ön şart değil, aynı zamanda günahların dökülmesine vesile olan bir ibadettir. Hz. Peygamber şöyle buyurmuştur: ''Mümin abdest aldığında günahları parmaklarının uçlarından dökülür.''","source":"Müslim, Tahâret 32"},"en":{"content":"Ablution is not only a prerequisite for prayer but an act of worship through which sins are shed. The Prophet said: ''When a believer performs ablution, the sins fall away from his fingertips.''","source":"Sahih Muslim, Purification 32"}}',true),

('worship','worship','evening','{"tr":{"content":"Tahajjüd namazı, farz namazların ardından en faziletli namazdır. Peygamberimiz gece namazını hiç terk etmemiştir. Rabbimiz şöyle buyurmuştur: ''Gece birazını da uyanık geçir; bu yalnızca sana has bir fazla ibadettir.'' (İsrâ 79)","source":"İsrâ Suresi, 79. Ayet; Müslim, Müsâfirîn 203"},"en":{"content":"The night prayer (Tahajjud) is the most virtuous prayer after the obligatory ones. Our Prophet never abandoned the night prayer. Allah said: ''And from the night, pray with it as additional worship for you.'' (Al-Isra 79)","source":"Surah Al-Isra, 17:79; Sahih Muslim, Travellers 203"}}',true),

('worship','worship','any','{"tr":{"content":"Hac, İslam''ın beş şartından biridir ve imkân bulan her Müslümana ömründe en az bir kez farzdır. Hz. Peygamber şöyle buyurmuştur: ''Kabul görmüş bir haccın karşılığı yalnızca cennettir.''","source":"Buhârî, Hac 4; Müslim, Hac 437"},"en":{"content":"Hajj is one of the five pillars of Islam and is obligatory for every capable Muslim at least once in a lifetime. The Prophet said: ''The reward of an accepted Hajj is nothing less than Paradise.''","source":"Sahih al-Bukhari, Hajj 4; Sahih Muslim, Hajj 437"}}',true),

('worship','worship','morning','{"tr":{"content":"Sabah ve akşam Allah''ı zikretmek, kalp huzurunun ve günlük bereketin anahtarıdır. Kur''ân''da şöyle buyurulur: ''Bilesiniz ki, kalpler ancak Allah''ı zikretmekle huzur bulur.'' (Ra''d 28)","source":"Ra''d Suresi, 28. Ayet"},"en":{"content":"Remembering Allah in the morning and evening is the key to peace of heart and daily blessing. The Quran says: ''Verily, in the remembrance of Allah do hearts find rest.'' (Ar-Ra''d 28)","source":"Surah Ar-Ra''d, 13:28"}}',true),

('worship','worship','noon','{"tr":{"content":"Müslüman kardeşine gıyabında dua etmek, kabul edilen duaların en kıymetlilerinden biridir. Hz. Peygamber şöyle buyurmuştur: ''Bir kişi kardeşine gıyabında dua ettiğinde, yanındaki melek ''Amin, sana da aynısı'' der.''","source":"Müslim, Zikr 86"},"en":{"content":"Praying for your Muslim brother in his absence is among the most precious accepted supplications. The Prophet said: ''When a person supplicates for his absent brother, the angel beside him says: Amen, and may you have the same.''","source":"Sahih Muslim, Dhikr 86"}}',true),

('worship','worship','any','{"tr":{"content":"Günahtan tevbe etmek de bir ibadettir. Allah, tevbe kapısını güneş batıdan doğana kadar kapatmayacağını müjdelemiştir. Her günah işleyenin önünde yeni bir başlangıç şansı vardır.","source":"Müslim, Tevbe 9"},"en":{"content":"Repenting from sin is itself an act of worship. Allah has promised that the door of repentance will not be closed until the sun rises from the west. Every sinner has a chance for a new beginning.","source":"Sahih Muslim, Repentance 9"}}',true),

('worship','worship','any','{"tr":{"content":"Ebeveynlere iyilik etmek, cihad dahil pek çok ibadetten daha faziletlidir. Hz. Peygamber, Allah''ın rızasının baba rızasında, Allah''ın kızgınlığının da babanın kızgınlığında gizli olduğunu söylemiştir.","source":"Tirmizî, Birr 3; sahih"},"en":{"content":"Being good to one''s parents is more virtuous than many acts of worship, including jihad. The Prophet said that the pleasure of Allah lies in the pleasure of the father and the anger of Allah lies in the anger of the father.","source":"Al-Tirmidhi, Righteousness 3 — sahih"}}',true),

('worship','worship','evening','{"tr":{"content":"Yatsı ve sabah namazlarını cemaatle kılmak büyük bir fazilettir. Hz. Peygamber şöyle buyurdu: ''Kim yatsı namazını cemaatle kılarsa, sanki gecenin yarısını namaz kılmış gibidir. Kim de sabah namazını cemaatle kılarsa, sanki bütün geceyi ibadetle geçirmiş gibidir.''","source":"Müslim, Mesâcid 260"},"en":{"content":"Praying Isha and Fajr in congregation holds great virtue. The Prophet said: ''Whoever prays Isha in congregation is as if he has prayed half the night. And whoever prays Fajr in congregation is as if he has prayed the entire night.''","source":"Sahih Muslim, Mosques 260"}}',true),

('worship','worship','any','{"tr":{"content":"Akraba ziyareti, ömrü uzatır ve rızkı genişletir. Hz. Peygamber şöyle buyurmuştur: ''Kim ömrünün uzamasını ve rızkının artmasını istiyorsa sıla-i rahim yapsın.''","source":"Buhârî, Edeb 12; Müslim, Birr 20"},"en":{"content":"Maintaining family ties lengthens life and expands provision. The Prophet said: ''Whoever wishes for his lifespan to be extended and his provision to be increased, let him maintain family ties.''","source":"Sahih al-Bukhari, Good Manners 12; Sahih Muslim, Virtue 20"}}',true),

('worship','worship','morning','{"tr":{"content":"Gün boyu helal kazanmaya çalışmak da bir ibadettir. Hz. Peygamber şöyle buyurmuştur: ''Kişinin helal kazanmak için çalışması farz ibadetlerden sonra en faziletli ibadettir.''","source":"Beyhakî, Şuabü''l-İman 8365; sahih"},"en":{"content":"Striving for lawful earnings throughout the day is itself an act of worship. The Prophet said: ''Seeking lawful earnings is an obligation after the obligatory acts of worship.''","source":"Al-Bayhaqi, Shu''ab al-Iman 8365 — sahih"}}',true),

('worship','worship','noon','{"tr":{"content":"İki kişi arasını bulmak ve aralarını ıslah etmek, en faziletli ibadetlerden biridir. Hz. Peygamber şöyle buyurdu: ''İki kişi arasını ıslah etmek, bütün nafile namaz ve oruçlardan daha faziletlidir.''","source":"Ebû Dâvûd, Edeb 50; sahih"},"en":{"content":"Reconciling between two people is one of the most virtuous acts of worship. The Prophet said: ''Reconciling between two people is better than all supererogatory prayers and fasts.''","source":"Abu Dawud, Good Manners 50 — sahih"}}',true),

('worship','worship','any','{"tr":{"content":"Bir Müslümanın ihtiyacını gidermek, onlarca nafila ibadetten daha değerlidir. Hz. Peygamber şöyle buyurmuştur: ''Allah''ın, kendi kullarına yardım ettiği müddetçe kuluna yardım etmesi, kulun kardeşinin ihtiyacını gidermek için çaba harcamasından geçer.''","source":"Müslim, Zikr 87"},"en":{"content":"Fulfilling the need of a Muslim is more valuable than many voluntary acts of worship. The Prophet said: ''Allah helps His servant as long as His servant helps his brother.''","source":"Sahih Muslim, Dhikr 87"}}',true),

('worship','worship','evening','{"tr":{"content":"Geceleri uyumadan önce okunacak dualar ve zikirler, kişiyi her türlü kötülükten korur ve uykuyu ibadete dönüştürür. Yatmadan önce abdestli olmak bu nimeti daha da artırır.","source":"Buhârî, Daavât 9; Ebû Dâvûd, Edeb 23"},"en":{"content":"The supplications and remembrances recited before sleeping protect a person from all evil and transform sleep into worship. Being in a state of purity before sleeping further increases this blessing.","source":"Sahih al-Bukhari, Invocations 9; Abu Dawud, Adab 23"}}',true),

('worship','dhikr','morning','{"tr":{"content":"Tesbih tanelerini kullanmak, Allah''ı zikirde yardımcı bir araçtır. Ancak Hz. Peygamber parmak boğumlarıyla saydığı için parmakla saymak da sünnettir. Önemli olan zikrin kalbe ulaşmasıdır.","source":"Ebû Dâvûd, Vitir 26; Tirmizî, Daavât 63"},"en":{"content":"Using prayer beads is a helpful tool for counting dhikr. However, counting on finger joints is also Sunnah since the Prophet used his fingers to count. What matters most is that the remembrance reaches the heart.","source":"Abu Dawud, Witr 26; Tirmidhi, Supplications 63"}}',true);

-- ============================================================
-- DHIKR (type='dhikr') — established adhkar with Arabic + transliteration
-- ============================================================

insert into public.content_items (type, category, recommended_time, translations, is_active) values

('dhikr','dhikr','any','{"tr":{"content":"''Sübhânallah'' — Allah''ı her türlü eksiklik ve noksanlıktan tenzih ederim. Her namazdan sonra 33 kez söylenmesi tavsiye edilir; kalbi temizler ve sevap hanesini doldurur.","arabicText":"سُبْحَانَ اللَّهِ","transliteration":"Sübhânallâh","source":"Buhârî, Daavât 65; Müslim, Mesâcid 146"},"en":{"content":"''Subhan Allah'' — Glory be to Allah; I declare Allah free from all imperfections. It is recommended to say it 33 times after each prayer. It purifies the heart and fills the record of good deeds.","arabicText":"سُبْحَانَ اللَّهِ","transliteration":"Subhan Allah","source":"Sahih al-Bukhari, Invocations 65; Sahih Muslim, Mosques 146"}}',true),

('dhikr','dhikr','any','{"tr":{"content":"''Elhamdülillah'' — Her türlü övgü ve şükür Allah''a mahsustur. Her namazdan sonra 33 kez söylenmesi tavsiye edilir; en faziletli dua olarak bildirilmiştir.","arabicText":"الْحَمْدُ لِلَّهِ","transliteration":"Elhamdülillâh","source":"Buhârî, Daavât 65; Tirmizî, Daavât 9"},"en":{"content":"''Alhamdulillah'' — All praise and thanks are due to Allah alone. It is recommended to say it 33 times after each prayer. It has been reported as the best of supplications.","arabicText":"الْحَمْدُ لِلَّهِ","transliteration":"Alhamdulillah","source":"Sahih al-Bukhari, Invocations 65; Tirmidhi, Supplications 9"}}',true),

('dhikr','dhikr','any','{"tr":{"content":"''Allahu Ekber'' — Allah her şeyden büyüktür. Her namazdan sonra 33 kez, ardından bir kez ''Lâ ilâhe illallâhü vahdehû lâ şerîke leh'' söylenmesi tavsiye edilir.","arabicText":"اللَّهُ أَكْبَرُ","transliteration":"Allâhu Ekber","source":"Müslim, Mesâcid 146; Buhârî, Ezân 155"},"en":{"content":"''Allahu Akbar'' — Allah is the Greatest. It is recommended to say it 33 times after each prayer followed once by ''La ilaha illallahu wahdahu la sharika lah.''","arabicText":"اللَّهُ أَكْبَرُ","transliteration":"Allahu Akbar","source":"Sahih Muslim, Mosques 146; Sahih al-Bukhari, Adhan 155"}}',true),

('dhikr','dhikr','any','{"tr":{"content":"''Lâ ilâhe illallâh'' — Allah''tan başka hiçbir ilah yoktur. Bu kelime-i tevhid, zikirler arasında en faziletlisidir ve ''Lâ havle...'' ile birlikte cennetin hazinelerinden sayılmaktadır.","arabicText":"لَا إِلَهَ إِلَّا اللَّهُ","transliteration":"Lâ ilâhe illallâh","source":"Tirmizî, Daavât 9; Buhârî, Daavât 50"},"en":{"content":"''La ilaha illallah'' — There is no deity but Allah. This declaration of tawhid is the most virtuous of all dhikr and is described together with ''La hawla...'' as one of the treasures of Paradise.","arabicText":"لَا إِلَهَ إِلَّا اللَّهُ","transliteration":"La ilaha illallah","source":"Al-Tirmidhi, Supplications 9; Sahih al-Bukhari, Invocations 50"}}',true),

('dhikr','dhikr','any','{"tr":{"content":"''Lâ ilâhe illallâhü vahdehû lâ şerîke leh, lehü''l-mülkü ve lehü''l-hamdü ve hüve alâ külli şey''in kadîr'' — Kim bunu günde yüz kez söylerse, on köle azad etmiş gibi sevap kazanır, yüz iyilik kaydedilir ve yüz günahı silinir.","arabicText":"لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ","transliteration":"Lâ ilâhe illallâhü vahdehû lâ şerîke leh, lehü''l-mülkü ve lehü''l-hamdü ve hüve alâ külli şey''in kadîr","source":"Buhârî, Bed''ü''l-Halk 11; Müslim, Zikr 28"},"en":{"content":"''La ilaha illallahu wahdahu la sharika lahu, lahul-mulku wa lahul-hamdu wa huwa ''ala kulli shay''in qadir'' — Whoever says this one hundred times a day will have a reward equivalent to freeing ten slaves, one hundred good deeds written for him and one hundred sins erased.","arabicText":"لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ","transliteration":"La ilaha illallahu wahdahu la sharika lahu lahul-mulku wa lahul-hamdu wa huwa ''ala kulli shay''in qadir","source":"Sahih al-Bukhari, Beginning of Creation 11; Sahih Muslim, Dhikr 28"}}',true),

('dhikr','dhikr','any','{"tr":{"content":"''Sübhânallâhi ve bihamdihî'' — Allah''ı hamd ile tenzih ederim. Hz. Peygamber şöyle buyurdu: ''Kim bunu günde yüz kez söylerse, denizin köpükleri kadar günah işlemiş olsa bile günahları bağışlanır.''","arabicText":"سُبْحَانَ اللَّهِ وَبِحَمْدِهِ","transliteration":"Sübhânallâhi ve bihamdihî","source":"Müslim, Zikr 28; Buhârî, Daavât 65"},"en":{"content":"''Subhan Allahi wa bihamdih'' — Glory and praise be to Allah. The Prophet said: ''Whoever says this a hundred times a day will have his sins forgiven even if they are as much as the foam of the sea.''","arabicText":"سُبْحَانَ اللَّهِ وَبِحَمْدِهِ","transliteration":"Subhan Allahi wa bihamdih","source":"Sahih Muslim, Dhikr 28; Sahih al-Bukhari, Invocations 65"}}',true),

('dhikr','dhikr','any','{"tr":{"content":"''Sübhânallâhi''l-Azîm'' — Yüce Allah''ı tenzih ederim. Hz. Peygamber şöyle buyurdu: ''Dile hafif, mizanda ağır, Rahman''a sevimli iki kelime vardır: Sübhânallahi ve bihamdih, Sübhânallahi''l-Azîm.''","arabicText":"سُبْحَانَ اللَّهِ الْعَظِيمِ","transliteration":"Sübhânallâhi''l-Azîm","source":"Buhârî, Daavât 65; Müslim, Zikr 31"},"en":{"content":"''Subhan Allahi''l-Azim'' — Glory be to Allah the Great. The Prophet said: ''Two words are light on the tongue, heavy in the scale and beloved to the Most Merciful: Subhan Allahi wa bihamdih, Subhan Allahi''l-Azim.''","arabicText":"سُبْحَانَ اللَّهِ الْعَظِيمِ","transliteration":"Subhan Allahi''l-Azim","source":"Sahih al-Bukhari, Invocations 65; Sahih Muslim, Dhikr 31"}}',true),

('dhikr','dhikr','any','{"tr":{"content":"''Lâ havle velâ kuvvete illâ billâh'' — Güç ve kuvvet yalnızca Allah''a aittir. Bu zikirle her türlü güçlüğü Allah''a havale ederiz. Hz. Peygamber bunu cennetin hazinelerinden biri olarak nitelendirmiştir.","arabicText":"لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ","transliteration":"Lâ havle velâ kuvvete illâ billâh","source":"Buhârî, Daavât 50; Müslim, Zikr 44"},"en":{"content":"''La hawla wa la quwwata illa billah'' — There is no might or power except with Allah. Through this remembrance we entrust all difficulties to Allah. The Prophet described it as one of the treasures of Paradise.","arabicText":"لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ","transliteration":"La hawla wa la quwwata illa billah","source":"Sahih al-Bukhari, Invocations 50; Sahih Muslim, Dhikr 44"}}',true),

('dhikr','dhikr','morning','{"tr":{"content":"Sabah ve akşam duası: ''Allah''ım! Sabaha erdiğimde ve akşama erdiğimde Seni, Arş''ını taşıyanları ve tüm meleklerini ve tüm yaratıklarını şahit tutuyorum ki Sen Allah''sın, Senden başka ilah yoktur, Sen teksin, ortağın yoktur. Hz. Muhammed Senin kuluн ve elçindir.'' (Dört kez)","arabicText":"اللَّهُمَّ إِنِّي أَصْبَحْتُ أُشْهِدُكَ وَأُشْهِدُ حَمَلَةَ عَرْشِكَ وَمَلَائِكَتَكَ وَجَمِيعَ خَلْقِكَ أَنَّكَ أَنْتَ اللَّهُ لَا إِلَهَ إِلَّا أَنْتَ وَحْدَكَ لَا شَرِيكَ لَكَ وَأَنَّ مُحَمَّدًا عَبْدُكَ وَرَسُولُكَ","transliteration":"Allâhümme innî asbahtu üşhidüke ve üşhidü hamele arşike ve melâ''iketeke ve cemîa halkıke enneke entellâhü lâ ilâhe illâ ente vahdeke lâ şerîke leke ve enne Muhammeden abdüke ve resûlük","source":"Ebû Dâvûd, Edeb 18; sahih"},"en":{"content":"Morning and evening supplication: ''O Allah, as I enter this morning I call You to witness, and I call to witness the bearers of Your Throne, Your angels and all Your creation, that You are Allah, there is no deity except You alone with no partner, and that Muhammad is Your servant and messenger.'' (Four times)","arabicText":"اللَّهُمَّ إِنِّي أَصْبَحْتُ أُشْهِدُكَ وَأُشْهِدُ حَمَلَةَ عَرْشِكَ وَمَلَائِكَتَكَ وَجَمِيعَ خَلْقِكَ أَنَّكَ أَنْتَ اللَّهُ لَا إِلَهَ إِلَّا أَنْتَ وَحْدَكَ لَا شَرِيكَ لَكَ وَأَنَّ مُحَمَّدًا عَبْدُكَ وَرَسُولُكَ","transliteration":"Allahumma inni asbahtu ushhiduka wa ushhidu hamalata ''arshika wa mala''ikataka wa jami''a khalqika annaka anta''llahu la ilaha illa anta wahdaka la sharika laka wa anna Muhammadan abduka wa rasuluk","source":"Abu Dawud, Adab 18 — sahih"}}',true),

('dhikr','dhikr','morning','{"tr":{"content":"''Allahümme innî es''elüke''l-afve ve''l-âfiyete fi''d-dünyâ ve''l-âhirah'' — ''Allah''ım! Senden dünya ve ahirette af ve afiyet istiyorum.'' Hz. Abbas bu duanın kendisine öğretilmesini Hz. Peygamber''den bizzat istemiştir.","arabicText":"اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ","transliteration":"Allâhümme innî es''elüke''l-afve ve''l-âfiyete fi''d-dünyâ ve''l-âhirah","source":"İbn Mâce, Duâ 2; sahih"},"en":{"content":"''O Allah, I ask You for pardon and well-being in this world and the Hereafter.'' Al-Abbas personally asked the Prophet to teach him this supplication.","arabicText":"اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ","transliteration":"Allahumma inni as''aluka''l-''afwa wa''l-''afiyata fi''d-dunya wa''l-akhirah","source":"Ibn Majah, Du''a 2 — sahih"}}',true),

('dhikr','dhikr','evening','{"tr":{"content":"''Hasbiyallâhü lâ ilâhe illâ hüve aleyhi tevekkeltü ve hüve rabbü''l-arşi''l-azîm'' — ''Allah bana yeter; O''ndan başka ilah yoktur; O''na tevekkül ettim; O yüce Arş''ın Rabbidir.'' Sabah ve akşam yedi kez okumak Hz. Peygamber tarafından tavsiye edilmiştir.","arabicText":"حَسْبِيَ اللَّهُ لَا إِلَهَ إِلَّا هُوَ عَلَيْهِ تَوَكَّلْتُ وَهُوَ رَبُّ الْعَرْشِ الْعَظِيمِ","transliteration":"Hasbiyallâhü lâ ilâhe illâ hüve aleyhi tevekkeltü ve hüve rabbü''l-arşi''l-azîm","source":"Ebû Dâvûd, Edeb 18; sahih"},"en":{"content":"''Allah is sufficient for me; there is no deity except Him. In Him I have placed my trust, and He is the Lord of the magnificent Throne.'' Reciting this seven times morning and evening was recommended by the Prophet.","arabicText":"حَسْبِيَ اللَّهُ لَا إِلَهَ إِلَّا هُوَ عَلَيْهِ تَوَكَّلْتُ وَهُوَ رَبُّ الْعَرْشِ الْعَظِيمِ","transliteration":"Hasbiyallahu la ilaha illa huwa ''alayhi tawakkaltu wa huwa rabbu''l-''arshi''l-azim","source":"Abu Dawud, Adab 18 — sahih"}}',true),

('dhikr','dhikr','morning','{"tr":{"content":"''Radîtü billâhi Rabben ve bi''l-İslâmi dînen ve bi Muhammedin nebiyyen'' — ''Rab olarak Allah''a, din olarak İslam''a, peygamber olarak Muhammed''e razı oldum.'' Sabah üç kez söylemek sünnettir.","arabicText":"رَضِيتُ بِاللَّهِ رَبًّا وَبِالْإِسْلَامِ دِينًا وَبِمُحَمَّدٍ نَبِيًّا","transliteration":"Radîtü billâhi Rabben ve bi''l-İslâmi dînen ve bi Muhammedin nebiyyen","source":"Ebû Dâvûd, Edeb 18; Tirmizî, Daavât 13 — sahih"},"en":{"content":"''I am pleased with Allah as my Lord, with Islam as my religion and with Muhammad as my prophet.'' Saying this three times in the morning is a Sunnah practice.","arabicText":"رَضِيتُ بِاللَّهِ رَبًّا وَبِالْإِسْلَامِ دِينًا وَبِمُحَمَّدٍ نَبِيًّا","transliteration":"Raditu billahi Rabban wa bi''l-Islami dinan wa bi Muhammadin nabiyyan","source":"Abu Dawud, Adab 18; Tirmidhi, Supplications 13 — sahih"}}',true),

('dhikr','dhikr','any','{"tr":{"content":"''Estağfirullâh'' — ''Allah''tan bağışlanma dilerim.'' Hz. Peygamber her gün yetmiş veya yüz kez istiğfar ederdi. İstiğfar, kalbi temizler ve rızık kapılarını açar.","arabicText":"أَسْتَغْفِرُ اللَّهَ","transliteration":"Estağfirullâh","source":"Buhârî, Daavât 3; Müslim, Zikr 41"},"en":{"content":"''Astaghfirullah'' — ''I seek forgiveness from Allah.'' The Prophet used to seek forgiveness seventy or one hundred times each day. Istighfar purifies the heart and opens the doors of provision.","arabicText":"أَسْتَغْفِرُ اللَّهَ","transliteration":"Astaghfirullah","source":"Sahih al-Bukhari, Invocations 3; Sahih Muslim, Dhikr 41"}}',true),

('dhikr','dhikr','any','{"tr":{"content":"''Estağfirullâhe''l-azîme ve etûbü ileyh'' — ''Yüce Allah''tan bağışlanma diler ve O''na tövbe ederim.'' Bu istiğfar formülü en kapsamlı olanlarından biridir.","arabicText":"أَسْتَغْفِرُ اللَّهَ الْعَظِيمَ وَأَتُوبُ إِلَيْهِ","transliteration":"Estağfirullâhe''l-azîme ve etûbü ileyh","source":"Tirmizî, Daavât 6; hasen"},"en":{"content":"''Astaghfirullahal-''azima wa atubu ilayh'' — ''I seek forgiveness from Allah the Great and I repent to Him.'' This formula of seeking forgiveness is among the most comprehensive.","arabicText":"أَسْتَغْفِرُ اللَّهَ الْعَظِيمَ وَأَتُوبُ إِلَيْهِ","transliteration":"Astaghfirullahal-''azima wa atubu ilayh","source":"Al-Tirmidhi, Supplications 6 — hasan"}}',true),

('dhikr','dhikr','morning','{"tr":{"content":"''Allahümme salli alâ Muhammedin ve alâ âli Muhammed'' — Salâvat-ı Şerife. Hz. Peygamber''e çokça salâvat getirmenin büyük fazileti vardır. Cuma günü özellikle tavsiye edilmiştir.","arabicText":"اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ","transliteration":"Allâhümme salli alâ Muhammedin ve alâ âli Muhammed","source":"Buhârî, Enbiyâ 10; Müslim, Salât 65"},"en":{"content":"''Allahumma salli ''ala Muhammadin wa ''ala ali Muhammad'' — The prayer upon the Prophet. Sending abundant salawat upon the Prophet carries great virtue and is especially recommended on Fridays.","arabicText":"اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ","transliteration":"Allahumma salli ''ala Muhammadin wa ''ala ali Muhammad","source":"Sahih al-Bukhari, Prophets 10; Sahih Muslim, Prayer 65"}}',true),

('dhikr','dhikr','evening','{"tr":{"content":"''Allahümme innî eûzü bike mine''l-hammi ve''l-hazen, ve eûzü bike mine''l-aczi ve''l-kesel...'' — Hz. Peygamber''in sıkıntı, üzüntü, acizlik, tembellik, cimrilik, korkaklık, borç ve insan baskısından Allah''a sığındığı dua.","arabicText":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ وَأَعُوذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ وَأَعُوذُ بِكَ مِنَ الْجُبْنِ وَالْبُخْلِ وَأَعُوذُ بِكَ مِنْ غَلَبَةِ الدَّيْنِ وَقَهْرِ الرِّجَالِ","transliteration":"Allâhümme innî eûzü bike mine''l-hammi ve''l-hazen ve eûzü bike mine''l-aczi ve''l-kesel ve eûzü bike mine''l-cübni ve''l-buhli ve eûzü bike min ğalebeti''d-deyni ve kahri''r-ricâl","source":"Buhârî, Daavât 39"},"en":{"content":"The Prophet''s supplication seeking refuge from worry, grief, incapacity, laziness, cowardice, miserliness, the burden of debt and the oppression of men.","arabicText":"اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ وَأَعُوذُ بِكَ مِنَ الْعَجْزِ وَالْكَسَلِ وَأَعُوذُ بِكَ مِنَ الْجُبْنِ وَالْبُخْلِ وَأَعُوذُ بِكَ مِنْ غَلَبَةِ الدَّيْنِ وَقَهْرِ الرِّجَالِ","transliteration":"Allahumma inni a''udhu bika mina''l-hammi wa''l-hazan wa a''udhu bika mina''l-''ajzi wa''l-kasal wa a''udhu bika mina''l-jubni wa''l-bukhli wa a''udhu bika min ghalabati''d-dayni wa qahri''r-rijal","source":"Sahih al-Bukhari, Invocations 39"}}',true),

('dhikr','dhikr','any','{"tr":{"content":"Tesbih-i Fâtıma: Namazlardan sonra Hz. Fâtıma''ya öğretilen zikir. ''Sübhânallah'' 33 kez, ''Elhamdülillah'' 33 kez, ''Allahu Ekber'' 33 kez ve sonunda ''Lâ ilâhe illallâhü vahdehû...'' bir kez. Bu zikir her türlü yorgunluğa devadır.","arabicText":"سُبْحَانَ اللَّهِ (٣٣) الْحَمْدُ لِلَّهِ (٣٣) اللَّهُ أَكْبَرُ (٣٣)","transliteration":"Sübhânallâh (33) — Elhamdülillâh (33) — Allâhu Ekber (33)","source":"Buhârî, Fedâilü''s-Sahâbe 9; Müslim, Zikr 80"},"en":{"content":"Tasbeeh of Fatimah: The dhikr taught to Lady Fatimah to recite after prayers. ''Subhan Allah'' 33 times, ''Alhamdulillah'' 33 times, ''Allahu Akbar'' 33 times followed once by the complete tahlil. This dhikr is a remedy for all fatigue.","arabicText":"سُبْحَانَ اللَّهِ (٣٣) الْحَمْدُ لِلَّهِ (٣٣) اللَّهُ أَكْبَرُ (٣٣)","transliteration":"Subhan Allah (33) — Alhamdulillah (33) — Allahu Akbar (33)","source":"Sahih al-Bukhari, Merits of Companions 9; Sahih Muslim, Dhikr 80"}}',true),

('dhikr','dhikr','evening','{"tr":{"content":"''Allahümme âfini fî bedeni, Allahümme âfini fî sem''î, Allahümme âfini fî basarî'' — ''Allah''ım! Bedenimde bana afiyet ver. Allah''ım! İşitmemde bana afiyet ver. Allah''ım! Görmemde bana afiyet ver.'' Sabah akşam üç kez.","arabicText":"اللَّهُمَّ عَافِنِي فِي بَدَنِي اللَّهُمَّ عَافِنِي فِي سَمْعِي اللَّهُمَّ عَافِنِي فِي بَصَرِي","transliteration":"Allâhümme âfini fî bedeni, Allâhümme âfini fî sem''î, Allâhümme âfini fî basarî","source":"Ebû Dâvûd, Edeb 18; hasen"},"en":{"content":"''O Allah, grant me health in my body. O Allah, grant me health in my hearing. O Allah, grant me health in my sight.'' Three times morning and evening.","arabicText":"اللَّهُمَّ عَافِنِي فِي بَدَنِي اللَّهُمَّ عَافِنِي فِي سَمْعِي اللَّهُمَّ عَافِنِي فِي بَصَرِي","transliteration":"Allahumma ''afini fi badani Allahumma ''afini fi sam''i Allahumma ''afini fi basari","source":"Abu Dawud, Adab 18 — hasan"}}',true),

('dhikr','dhikr','morning','{"tr":{"content":"''Allahümme innî esbahtu minke fî ni''metin ve âfiyetin ve setrin, fe etimme ni''meteke aleyye ve âfiyeteke ve setreke fi''d-dünyâ ve''l-âhirah'' — Sabah nimetlerin farkında olarak güne başlamak için okunur.","arabicText":"اللَّهُمَّ إِنِّي أَصْبَحْتُ مِنْكَ فِي نِعْمَةٍ وَعَافِيَةٍ وَسِتْرٍ فَأَتِمَّ نِعْمَتَكَ عَلَيَّ وَعَافِيَتَكَ وَسِتْرَكَ فِي الدُّنْيَا وَالْآخِرَةِ","transliteration":"Allâhümme innî esbahtu minke fî ni''metin ve âfiyetin ve setrin, fe etimme ni''meteke aleyye ve âfiyeteke ve setreke fi''d-dünyâ ve''l-âhirah","source":"İbn Hibbân; sahih"},"en":{"content":"''O Allah, I have entered this morning while You have blessed me with well-being, health and covering, so complete Your blessing, health and covering upon me in this world and the Hereafter.'' Recited in the morning with awareness of Allah''s blessings.","arabicText":"اللَّهُمَّ إِنِّي أَصْبَحْتُ مِنْكَ فِي نِعْمَةٍ وَعَافِيَةٍ وَسِتْرٍ فَأَتِمَّ نِعْمَتَكَ عَلَيَّ وَعَافِيَتَكَ وَسِتْرَكَ فِي الدُّنْيَا وَالْآخِرَةِ","transliteration":"Allahumma inni asbahtu minka fi ni''matin wa ''afiyatin wa sitrin fa atimma ni''mataka ''alayya wa ''afiyataka wa sitraka fi''d-dunya wa''l-akhirah","source":"Ibn Hibban — sahih"}}',true),

('dhikr','dhikr','any','{"tr":{"content":"İhlâs Suresi: ''De ki: O, Allah''tır, bir tektir. Allah Samed''dir. Doğurmamış ve doğurulmamıştır. Hiçbir şey O''na denk ve benzer değildir.'' Bu sure Kur''ân''ın üçte birine denktir.","arabicText":"قُلْ هُوَ اللَّهُ أَحَدٌ اللَّهُ الصَّمَدُ لَمْ يَلِدْ وَلَمْ يُولَدْ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ","transliteration":"Kul hüvallâhü ehad, Allâhü''s-samed, lem yelid ve lem yûled, ve lem yekün lehû küfüven ehad","source":"Buhârî, Fedâilü''l-Kur''ân 13; İhlâs Suresi 1-4"},"en":{"content":"Surah Al-Ikhlas: ''Say: He is Allah, the One. Allah, the Eternal Refuge. He neither begets nor is born. Nor is there to Him any equivalent.'' This surah equals one third of the Quran in reward.","arabicText":"قُلْ هُوَ اللَّهُ أَحَدٌ اللَّهُ الصَّمَدُ لَمْ يَلِدْ وَلَمْ يُولَدْ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ","transliteration":"Qul huwa''llahu ahad Allahu''s-samad lam yalid wa lam yulad wa lam yakun lahu kufuwan ahad","source":"Sahih al-Bukhari, Virtues of the Quran 13; Surah Al-Ikhlas 112:1-4"}}',true),

('dhikr','dhikr','any','{"tr":{"content":"Haşr Suresi''nin son üç ayeti büyük fazileti olan bir zikirdir. Hz. Peygamber şöyle buyurdu: ''Kim sabah ''E''ûzü billâhi''s-Semî''il-Alîm mine''ş-şeytânirracîm'' deyip Haşr Suresi''nin son üç ayetini okursa yetmiş bin melek akşama kadar onun için dua eder.''","arabicText":"هُوَ اللَّهُ الَّذِي لَا إِلَهَ إِلَّا هُوَ عَالِمُ الْغَيْبِ وَالشَّهَادَةِ هُوَ الرَّحْمَنُ الرَّحِيمُ","transliteration":"Huvallâhüllezî lâ ilâhe illâ hüve, âlimü''l-ğaybi ve''ş-şehâdeti, hüve''r-rahmânü''r-rahîm","source":"Tirmizî, Daavât 22; hasen — Haşr Suresi 22-24"},"en":{"content":"The last three verses of Surah Al-Hashr are a remembrance of great virtue. The Prophet said: ''Whoever says the ta''awwudh and then recites the last three verses of Al-Hashr in the morning, seventy thousand angels will pray for him until evening.''","arabicText":"هُوَ اللَّهُ الَّذِي لَا إِلَهَ إِلَّا هُوَ عَالِمُ الْغَيْبِ وَالشَّهَادَةِ هُوَ الرَّحْمَنُ الرَّحِيمُ","transliteration":"Huwa''llahu''lladhi la ilaha illa huwa ''alimu''l-ghaybi wa''sh-shahadati huwa''r-rahmanu''r-rahim","source":"Al-Tirmidhi, Supplications 22 — hasan; Surah Al-Hashr 59:22-24"}}',true),

('dhikr','dhikr','morning','{"tr":{"content":"''Allahümme ente rabbi lâ ilâhe illâ ente halaktenî ve ene abdüke...'' Seyyidü''l-İstiğfar — Sabah okuyup henüz akşam olmadan şehit olursa cennetliktir; akşam okuyup sabah olmadan ölürse cennetliktir.","arabicText":"اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلَّا أَنْتَ خَلَقْتَنِي وَأَنَا عَبْدُكَ","transliteration":"Allâhümme ente Rabbî lâ ilâhe illâ ente halaktenî ve ene abdük...","source":"Buhârî, Daavât 2"},"en":{"content":"The Master of Istighfar — Whoever says it in the morning with conviction and dies before evening is among the people of Paradise; whoever says it in the evening with conviction and dies before morning is among the people of Paradise.","arabicText":"اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلَّا أَنْتَ خَلَقْتَنِي وَأَنَا عَبْدُكَ","transliteration":"Allahumma anta Rabbi la ilaha illa anta khalaqtani wa ana abduk...","source":"Sahih al-Bukhari, Invocations 2"}}',true),

('dhikr','dhikr','any','{"tr":{"content":"''Sübhânallâhi ve bihamdihî, sübhânallâhi''l-azîm'' — Bu iki cümle dile hafif, mizanda ağır ve Rahman''a sevimlidir. Kur''ân''da da ''Rabb''ini hamd ile tesbih et'' emri geçmektedir.","arabicText":"سُبْحَانَ اللَّهِ وَبِحَمْدِهِ سُبْحَانَ اللَّهِ الْعَظِيمِ","transliteration":"Sübhânallâhi ve bihamdihî, sübhânallâhi''l-azîm","source":"Buhârî, Daavât 65; Müslim, Zikr 31"},"en":{"content":"''Subhan Allahi wa bihamdih, Subhan Allahi''l-Azim'' — These two phrases are light on the tongue, heavy on the scale and beloved to the Most Merciful. The Quran too commands ''glorify your Lord with praise.''","arabicText":"سُبْحَانَ اللَّهِ وَبِحَمْدِهِ سُبْحَانَ اللَّهِ الْعَظِيمِ","transliteration":"Subhan Allahi wa bihamdih, Subhan Allahi''l-Azim","source":"Sahih al-Bukhari, Invocations 65; Sahih Muslim, Dhikr 31"}}',true),

('dhikr','dhikr','any','{"tr":{"content":"''Bismillâhirrahmânirrahîm'' — ''Rahman ve Rahim olan Allah''ın adıyla.'' Her işe bununla başlamak sünnettir. Kur''ân-ı Kerîm''in her suresi bu cümleyle başlar.","arabicText":"بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ","transliteration":"Bismillâhirrahmânirrahîm","source":"Kur''ân-ı Kerîm, Naml 30; Buhârî, Bed''ü''l-Halk 1"},"en":{"content":"''Bismillahir-rahmanir-rahim'' — ''In the name of Allah, the Most Gracious, the Most Merciful.'' Beginning every action with this is Sunnah. Every surah of the Quran begins with this phrase.","arabicText":"بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ","transliteration":"Bismillahir-rahmanir-rahim","source":"Quran, An-Naml 27:30; Sahih al-Bukhari, Beginning of Creation 1"}}',true),

('dhikr','dhikr','evening','{"tr":{"content":"Yatmadan önce ''Âyetü''l-Kürsî'' okumak şeytandan korur. Hz. Peygamber şöyle buyurdu: ''Kim bu ayeti okursa, onu sabah olana kadar Allah tarafından görevlendirilmiş bir muhafız korur, şeytan ona yaklaşamaz.''","arabicText":"اللَّهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ","transliteration":"Allâhu lâ ilâhe illâ hüve''l-hayyü''l-kayyûm...","source":"Buhârî, Vekâle 10"},"en":{"content":"Reciting Ayat al-Kursi before sleeping protects against Satan. The Prophet said: ''Whoever recites it, an appointed guardian from Allah will protect him until morning and Satan cannot approach him.''","arabicText":"اللَّهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ","transliteration":"Allahu la ilaha illa huwa''l-hayyu''l-qayyum...","source":"Sahih al-Bukhari, Agency 10"}}',true),

('dhikr','dhikr','morning','{"tr":{"content":"''Allahümme innî es''elüke''l-hüdâ ve''t-tükâ ve''l-afâfe ve''l-ğinâ'' — ''Allah''ım! Senden hidayet, takva, iffet ve gönül zenginliği istiyorum.'' Hz. Peygamber bu duayı düzenli okurlardı.","arabicText":"اللَّهُمَّ إِنِّي أَسْأَلُكَ الْهُدَى وَالتُّقَى وَالْعَفَافَ وَالْغِنَى","transliteration":"Allâhümme innî es''elüke''l-hüdâ ve''t-tükâ ve''l-afâfe ve''l-ğinâ","source":"Müslim, Zikr 72"},"en":{"content":"''O Allah, I ask You for guidance, piety, chastity and contentment.'' The Prophet used to recite this supplication regularly.","arabicText":"اللَّهُمَّ إِنِّي أَسْأَلُكَ الْهُدَى وَالتُّقَى وَالْعَفَافَ وَالْغِنَى","transliteration":"Allahumma inni as''aluka''l-huda wa''t-tuqa wa''l-''afafa wa''l-ghina","source":"Sahih Muslim, Dhikr 72"}}',true),

('dhikr','dhikr','any','{"tr":{"content":"''Yâ Hayyu yâ Kayyûm, bi rahmetike esteğîs'' — ''Ey diri ve her şeyi ayakta tutan! Rahmetinle yardım istiyorum.'' Hz. Peygamber sıkıntı anında bu zikri okurdu.","arabicText":"يَا حَيُّ يَا قَيُّومُ بِرَحْمَتِكَ أَسْتَغِيثُ","transliteration":"Yâ Hayyu yâ Kayyûm, bi rahmetike esteğîs","source":"Tirmizî, Daavât 22; hasen"},"en":{"content":"''O Ever-Living, O Self-Sustaining, I seek help through Your mercy.'' The Prophet would recite this dhikr in times of distress.","arabicText":"يَا حَيُّ يَا قَيُّومُ بِرَحْمَتِكَ أَسْتَغِيثُ","transliteration":"Ya Hayyu ya Qayyum bi rahmatika astaghith","source":"Al-Tirmidhi, Supplications 22 — hasan"}}',true);
